export const jlpt = [{"id":"ja-j-0001","level":1,"section":"moji","mondai":1,"stem":"あの 人は 学生 です。","underline":"学生","options":["かくせ","かくせい","がくせ","がくせい"],"answer":"がくせい","note":"「学生」讀「がくせい」：「学」是濁音「がく」，「生」是長音「せい」。「かくせい」少了濁音，「がくせ」少了長音。"},{"id":"ja-j-0002","level":1,"section":"moji","mondai":1,"stem":"きのう 先生 に あいました。","underline":"先生","options":["せんせえ","せんぜい","せんせ","せんせい"],"answer":"せんせい","note":"「先生」讀「せんせい」，「生」的長音寫成「せい」。「せんせえ」是照口語發音拼的寫法，不是正確假名；「せんせ」少了長音，「せんぜい」多了濁音。"},{"id":"ja-j-0003","level":1,"section":"moji","mondai":1,"stem":"学校 は いえから ちかいです。","underline":"学校","options":["かっこう","がっこう","かっこ","がっこ"],"answer":"がっこう","note":"「学校」讀「がっこう」：「学」在這裡變成促音「がっ」，「校」是長音「こう」。「かっこう」少了濁音，「がっこ」少了長音。"},{"id":"ja-j-0004","level":1,"section":"moji","mondai":1,"stem":"大学 で にほんごを べんきょうします。","underline":"大学","options":["たいかく","だいかく","たいがく","だいがく"],"answer":"だいがく","note":"「大学」讀「だいがく」，「大」的「だい」和「学」的「がく」都是濁音。「たいがく」「だいかく」各少了一個濁音。"},{"id":"ja-j-0005","level":1,"section":"moji","mondai":1,"stem":"ちちは 会社員 です。","underline":"会社員","options":["かいしゃいん","がいしゃいん","かいしゃじん","かいさいん"],"answer":"かいしゃいん","note":"「会社員」讀「かいしゃいん」：「会社」是「かいしゃ」，「員」讀「いん」。「かいさいん」把拗音「しゃ」寫成「さ」，「かいしゃじん」把「員」誤讀成「じん」。"},{"id":"ja-j-0006","level":1,"section":"moji","mondai":1,"stem":"日本 に すんで います。","underline":"日本","options":["にっほん","にほん","ひほん","にぼん"],"answer":"にほん","note":"「日本」讀「にほん」。「にっほん」多了促音，「にぼん」把「ほ」誤成濁音，「ひほん」是把「日」讀成訓讀的「ひ」。"},{"id":"ja-j-0007","level":1,"section":"moji","mondai":1,"stem":"日本語 が すこし わかります。","underline":"日本語","options":["にほんごう","にぼんご","にほんこ","にほんご"],"answer":"にほんご","note":"「日本語」讀「にほんご」，「語」是濁音「ご」。「にほんこ」少了濁音，「にほんごう」多了長音，「にぼんご」把「ほ」誤成濁音。"},{"id":"ja-j-0008","level":1,"section":"moji","mondai":1,"stem":"中国 へ いった ことが あります。","underline":"中国","options":["ちゅごく","ちゅうこく","ちゅうごく","ちゅごこく"],"answer":"ちゅうごく","note":"「中国」讀「ちゅうごく」：「中」是長音「ちゅう」，「国」在這裡變成濁音「ごく」。「ちゅごく」少了長音，「ちゅうこく」少了濁音。"},{"id":"ja-j-0009","level":1,"section":"moji","mondai":1,"stem":"きょうは 月曜日 です。","underline":"月曜日","options":["げっつようび","げつようび","もくようび","かようび"],"answer":"げつようび","note":"「月曜日」讀「げつようび」，星期裡的「月」讀「げつ」。「げっつようび」多了促音；「もくようび」是「木曜日」，「かようび」是「火曜日」。"},{"id":"ja-j-0010","level":1,"section":"moji","mondai":1,"stem":"水曜日 に プールへ いきます。","underline":"水曜日","options":["かようび","すいようび","もくようび","みずようび"],"answer":"すいようび","note":"「水曜日」讀「すいようび」，「水」用音讀「すい」。「みずようび」誤用了訓讀「みず」；「かようび」「もくようび」是別的星期。"},{"id":"ja-j-0011","level":1,"section":"moji","mondai":1,"stem":"金曜日 の よる、ともだちと あいます。","underline":"金曜日","options":["どようび","かようび","げつようび","きんようび"],"answer":"きんようび","note":"「金曜日」讀「きんようび」，「金」用音讀「きん」。「どようび」是「土曜日」，「かようび」是「火曜日」，「げつようび」是「月曜日」。"},{"id":"ja-j-0012","level":1,"section":"moji","mondai":1,"stem":"土曜日 は やすみです。","underline":"土曜日","options":["つちようび","とようび","どようび","どっようび"],"answer":"どようび","note":"「土曜日」讀「どようび」，「土」是濁音「ど」。「とようび」少了濁音，「つちようび」誤用了訓讀「つち」，「どっようび」多了促音。"},{"id":"ja-j-0013","level":1,"section":"moji","mondai":1,"stem":"日曜日 に かぞくと こうえんへ いきました。","underline":"日曜日","options":["にっようび","げつようび","ひようび","にちようび"],"answer":"にちようび","note":"「日曜日」讀「にちようび」，「日」在這裡用音讀「にち」。「にっようび」把「ち」誤成促音，「ひようび」誤用了訓讀「ひ」，「げつようび」是「月曜日」。"},{"id":"ja-j-0014","level":1,"section":"moji","mondai":1,"stem":"きょうは 十月 ついたちです。","underline":"十月","options":["しがつ","はちがつ","じゅうがつ","じゅういちがつ"],"answer":"じゅうがつ","note":"「十月」讀「じゅうがつ」，月份的「月」讀「がつ」。「しがつ」是四月，「はちがつ」是八月，「じゅういちがつ」是十一月。"},{"id":"ja-j-0015","level":1,"section":"moji","mondai":1,"stem":"九月 に がっこうが はじまります。","underline":"九月","options":["くつき","きゅうがつ","ここのがつ","くがつ"],"answer":"くがつ","note":"「九月」讀「くがつ」，月份裡的「九」固定讀「く」，不讀「きゅう」。「きゅうがつ」是最常見的錯誤，「ここのがつ」「くつき」也都不是月份的讀法。"},{"id":"ja-j-0016","level":1,"section":"moji","mondai":1,"stem":"七月 は あついです。","underline":"七月","options":["なながつ","なのがつ","しちがつ","ななつき"],"answer":"しちがつ","note":"「七月」讀「しちがつ」，月份裡的「七」讀「しち」。「なながつ」是把數數用的「なな」套進來，「なのがつ」「ななつき」也不是月份的讀法。"},{"id":"ja-j-0017","level":1,"section":"moji","mondai":1,"stem":"四月 から 大学に いきます。","underline":"四月","options":["しがつ","よがつ","よんがつ","よっがつ"],"answer":"しがつ","note":"「四月」讀「しがつ」，月份裡的「四」固定讀「し」。「よんがつ」「よがつ」是把數數用的「よん」「よ」套進來，「よっがつ」多了促音。"},{"id":"ja-j-0018","level":1,"section":"moji","mondai":1,"stem":"今日 は とても いい てんきです。","underline":"今日","options":["きょう","こんにち","こんじつ","きょうび"],"answer":"きょう","note":"「今日」讀「きょう」，是整個詞一起記的特殊讀法。「こんにち」意思是「如今、現今」，不用來說今天天氣好；「こんじつ」「きょうび」也不合這句。"},{"id":"ja-j-0019","level":1,"section":"moji","mondai":1,"stem":"今年の ふゆは さむいです。","underline":"今年","options":["ことし","こんねん","いまとし","きんねん"],"answer":"ことし","note":"「今年」讀「ことし」，是整個詞一起記的特殊讀法。「こんねん」是很正式的書面說法，不用在日常聊天氣；「いまとし」是逐字硬讀，「きんねん」是「近年」。"},{"id":"ja-j-0020","level":1,"section":"moji","mondai":1,"stem":"先月 たんじょうびでした。","underline":"先月","options":["せんがつ","ぜんげつ","せんげつ","ぜんがつ"],"answer":"せんげつ","note":"「先月」讀「せんげつ」，表示「上個月」時「月」讀「げつ」。「せんがつ」誤用了月份名稱的「がつ」，「ぜんげつ」「ぜんがつ」把「先」誤成濁音。"},{"id":"ja-j-0021","level":1,"section":"moji","mondai":1,"stem":"来週 りょこうに いきます。","underline":"来週","options":["らいしゅ","こんしゅう","らいしゅう","せんしゅう"],"answer":"らいしゅう","note":"「来週」讀「らいしゅう」，「週」是長音「しゅう」。「らいしゅ」少了長音；「こんしゅう」是本週，「せんしゅう」是上週。"},{"id":"ja-j-0022","level":1,"section":"moji","mondai":1,"stem":"毎日 にほんごを べんきょうします。","underline":"毎日","options":["まいにち","まいひ","まいじつ","まいか"],"answer":"まいにち","note":"「毎日」讀「まいにち」，「日」在這裡用音讀「にち」。「まいひ」誤用了訓讀「ひ」，「まいじつ」「まいか」也不是這個詞的讀法。"},{"id":"ja-j-0023","level":1,"section":"moji","mondai":1,"stem":"午前 くじに がっこうへ いきます。","underline":"午前","options":["くぜん","ごご","しょうご","ごぜん"],"answer":"ごぜん","note":"「午前」讀「ごぜん」：「午」讀「ご」，「前」是濁音「ぜん」。「ごご」是「午後」，「しょうご」是「正午」，「くぜん」不是任何詞的讀法。"},{"id":"ja-j-0024","level":1,"section":"moji","mondai":1,"stem":"午後 さんじに あいましょう。","underline":"午後","options":["ごぜん","ごこ","ごご","ごう"],"answer":"ごご","note":"「午後」讀「ごご」，兩個字都讀濁音「ご」。「ごぜん」是「午前」，「ごこ」把第二個「ご」誤成清音，「ごう」把第二個「ご」寫成了長音。"},{"id":"ja-j-0025","level":1,"section":"moji","mondai":1,"stem":"ごじ半 に いえに かえります。","underline":"半","options":["ばん","はん","なか","ぱん"],"answer":"はん","note":"「半」讀「はん」，「ごじ半」就是五點半。「ばん」誤加了濁音，「ぱん」誤加了半濁音，「なか」是「中」的讀法。"},{"id":"ja-j-0026","level":1,"section":"moji","mondai":1,"stem":"きょうは 何曜日 ですか。","underline":"何曜日","options":["どようび","なにようび","かようび","なんようび"],"answer":"なんようび","note":"「何曜日」讀「なんようび」，「何」接「曜日」時讀「なん」。「なにようび」是常見錯誤；「どようび」「かようび」是具體的星期，不是問句。"},{"id":"ja-j-0027","level":1,"section":"moji","mondai":1,"stem":"何時 に きますか。","underline":"何時","options":["なじ","なんじ","いつじ","なにじ"],"answer":"なんじ","note":"「何時」讀「なんじ」，問幾點時「何」讀「なん」。「なにじ」是常見錯誤，「なじ」少了「ん」，「いつじ」不是這個詞的讀法。"},{"id":"ja-j-0028","level":1,"section":"moji","mondai":1,"stem":"つくえの 上 に ほんが あります。","underline":"上","options":["うる","うへ","うい","うえ"],"answer":"うえ","note":"「上」單獨使用時讀訓讀「うえ」。「うへ」是舊假名的寫法，現代寫成「うえ」；「うる」「うい」都不是這個字的讀法。"},{"id":"ja-j-0029","level":1,"section":"moji","mondai":1,"stem":"ねこは いすの 下 に います。","underline":"下","options":["しだ","した","しぢ","しと"],"answer":"した","note":"「下」單獨使用時讀「した」。「しだ」多了濁音，「しぢ」「しと」都不是這個字的讀法。"},{"id":"ja-j-0030","level":1,"section":"moji","mondai":1,"stem":"右 に まがって ください。","underline":"右","options":["みき","みぎ","みじ","みち"],"answer":"みぎ","note":"「右」讀「みぎ」，最後是濁音「ぎ」。「みき」少了濁音，「みち」是「道」，「みじ」不是任何詞的讀法。"},{"id":"ja-j-0031","level":1,"section":"moji","mondai":1,"stem":"左 がわに 大きい きが あります。","underline":"左","options":["ひがり","ひだり","ひたり","ひだい"],"answer":"ひだり","note":"「左」讀「ひだり」，中間是濁音「だ」。「ひたり」少了濁音，「ひがり」「ひだい」各錯了一個音。"},{"id":"ja-j-0032","level":1,"section":"moji","mondai":1,"stem":"ぎんこうの 前 に コンビニが あります。","underline":"前","options":["まい","まえ","まへ","もえ"],"answer":"まえ","note":"「前」單獨使用時讀「まえ」。「まへ」是舊假名的寫法，現代寫成「まえ」；「まい」「もえ」各錯了一個音。"},{"id":"ja-j-0033","level":1,"section":"moji","mondai":1,"stem":"学校の 後ろ に こうえんが あります。","underline":"後ろ","options":["あしろ","うしる","うしろ","うじろ"],"answer":"うしろ","note":"「後ろ」讀「うしろ」，最後的「ろ」是寫在漢字後面的送假名。「うじろ」多了濁音，「うしる」「あしろ」各錯了一個音。"},{"id":"ja-j-0034","level":1,"section":"moji","mondai":1,"stem":"きょうは さむいので、外 へ でません。","underline":"外","options":["そど","そと","さと","のそと"],"answer":"そと","note":"「外」單獨使用時讀「そと」。「そど」多了濁音，「さと」錯了母音，「のそと」多了「の」。"},{"id":"ja-j-0035","level":1,"section":"moji","mondai":1,"stem":"私の いえは まちの 北 に あります。","underline":"北","options":["きた","きだ","ほく","ぼく"],"answer":"きた","note":"「北」單獨表示方位時讀訓讀「きた」。「ほく」是音讀，只出現在「北部」這類複合詞裡；「きだ」「ぼく」是把清音誤成濁音。"},{"id":"ja-j-0036","level":1,"section":"moji","mondai":1,"stem":"山 の うえに ゆきが あります。","underline":"山","options":["やみ","やめ","やま","やも"],"answer":"やま","note":"「山」讀「やま」。「やみ」「やめ」「やも」都是把第二個音的母音弄錯了。"},{"id":"ja-j-0037","level":1,"section":"moji","mondai":1,"stem":"川 で さかなを みました。","underline":"川","options":["かれ","かは","かわ","かや"],"answer":"かわ","note":"「川」讀「かわ」。「かは」是舊假名的寫法，現代寫成「かわ」；「かれ」「かや」都不是這個字的讀法。"},{"id":"ja-j-0038","level":1,"section":"moji","mondai":1,"stem":"きょうは 天気 が いいです。","underline":"天気","options":["でんぎ","でんき","てんぎ","てんき"],"answer":"てんき","note":"「天気」讀「てんき」，兩個字都是清音。「てんぎ」「でんぎ」多了濁音；「でんき」是「電気」，意思是電。"},{"id":"ja-j-0039","level":1,"section":"moji","mondai":1,"stem":"雨 が ふって います。","underline":"雨","options":["うめ","あま","あみ","あめ"],"answer":"あめ","note":"「雨」單獨使用時讀「あめ」。「あま」只出現在「雨戸」這類複合詞裡；「うめ」是「梅」，「あみ」是「網」。"},{"id":"ja-j-0040","level":1,"section":"moji","mondai":1,"stem":"花 が きれいに さいて います。","underline":"花","options":["ばな","はね","はま","はな"],"answer":"はな","note":"「花」單獨使用時讀「はな」。「ばな」只在「生け花」這類複合詞後半才變濁音；「はね」「はま」是別的詞。"},{"id":"ja-j-0041","level":1,"section":"moji","mondai":1,"stem":"電車 で 駅まで いきます。","underline":"電車","options":["でんさ","てんしゃ","でんしゃ","てんさ"],"answer":"でんしゃ","note":"「電車」讀「でんしゃ」：「電」是濁音「でん」，「車」是拗音「しゃ」。「てんしゃ」少了濁音，「でんさ」把「しゃ」寫成「さ」。"},{"id":"ja-j-0042","level":1,"section":"moji","mondai":1,"stem":"電話 ばんごうを おしえて ください。","underline":"電話","options":["でんわ","てんわ","でんは","てんは"],"answer":"でんわ","note":"「電話」讀「でんわ」，「話」在這裡讀「わ」。「てんわ」少了濁音；「でんは」把「わ」寫成「は」，只有助詞「は」才唸成「わ」。"},{"id":"ja-j-0043","level":1,"section":"moji","mondai":1,"stem":"駅 の まえで まって います。","underline":"駅","options":["えき","えぎ","えく","やき"],"answer":"えき","note":"「駅」讀「えき」。「えぎ」多了濁音，「えく」錯了母音，「やき」第一個音就不對。"},{"id":"ja-j-0044","level":1,"section":"moji","mondai":1,"stem":"その 店 で パンを 買いました。","underline":"店","options":["みせ","みぜ","みす","みえ"],"answer":"みせ","note":"「店」單獨使用時讀訓讀「みせ」。「みぜ」多了濁音，「みす」「みえ」各錯了一個音。"},{"id":"ja-j-0045","level":1,"section":"moji","mondai":1,"stem":"新しい ノートを 買いました。","underline":"新しい","options":["あたらしい","あらたしい","あだらしい","あたうしい"],"answer":"あたらしい","note":"「新しい」讀「あたらしい」，順序是「あ・た・ら」。「あらたしい」把「た」「ら」對調，「あだらしい」多了濁音，「あたうしい」錯了一個音。"},{"id":"ja-j-0046","level":1,"section":"moji","mondai":1,"stem":"この くつは 古い です。","underline":"古い","options":["ふろい","ふるい","ぶるい","ふらい"],"answer":"ふるい","note":"「古い」讀「ふるい」。「ぶるい」多了濁音，「ふろい」「ふらい」把「る」的母音弄錯了。"},{"id":"ja-j-0047","level":1,"section":"moji","mondai":1,"stem":"この かばんは 高い です。","underline":"高い","options":["たがい","たかい","たけい","だかい"],"answer":"たかい","note":"「高い」讀「たかい」，前兩個音都是清音。「たがい」「だかい」各多了一個濁音，「たけい」錯了母音。"},{"id":"ja-j-0048","level":1,"section":"moji","mondai":1,"stem":"安い くつを 買いました。","underline":"安い","options":["あすい","やすい","やしい","やせい"],"answer":"やすい","note":"「安い」讀「やすい」。「あすい」第一個音不對，「やしい」「やせい」把「す」的母音弄錯了。"},{"id":"ja-j-0049","level":1,"section":"moji","mondai":1,"stem":"白い いぬが います。","underline":"白い","options":["しろい","しらい","じろい","しろう"],"answer":"しろい","note":"「白い」讀「しろい」。「じろい」多了濁音，「しらい」錯了母音，「しろう」的詞尾不是形容詞的「い」。"},{"id":"ja-j-0050","level":1,"section":"moji","mondai":1,"stem":"この みちは 長い です。","underline":"長い","options":["ながい","なかい","のがい","ねがい"],"answer":"ながい","note":"「長い」讀「ながい」，中間是濁音「が」。「なかい」少了濁音，「ねがい」是「願い」，「のがい」不是詞。"},{"id":"ja-j-0051","level":1,"section":"moji","mondai":2,"stem":"あの がくせい は とても しんせつです。","underline":"がくせい","options":["学先","字生","学生","字先"],"answer":"学生","note":"「がくせい」寫成「学生」。「字」和「学」上半部很像但是不同的字，「先」是「先生」的「先」，換進來都不成詞。"},{"id":"ja-j-0052","level":1,"section":"moji","mondai":2,"stem":"せんせい に しつもんを しました。","underline":"せんせい","options":["先成","先正","先生","元生"],"answer":"先生","note":"「せんせい」寫成「先生」。「先成」「先正」把「生」換成同樣讀「せい」的字，「元生」把「先」換成形近的「元」，都不是詞。"},{"id":"ja-j-0053","level":1,"section":"moji","mondai":2,"stem":"がっこう で にほんごを べんきょうします。","underline":"がっこう","options":["字交","字校","学交","学校"],"answer":"学校","note":"「がっこう」寫成「学校」。「字」和「学」形近，「交」比「校」少了木字旁，組成的「字交」「字校」「学交」都不是詞。"},{"id":"ja-j-0054","level":1,"section":"moji","mondai":2,"stem":"うちの 父は とても ちから が つよいです。","underline":"ちから","options":["力","刀","万","方"],"answer":"力","note":"「ちから」寫成「力」。「刀」（かたな）和「力」最容易看錯，「万」「方」也是形近字，都不讀「ちから」。"},{"id":"ja-j-0055","level":1,"section":"moji","mondai":2,"stem":"この えいがは おとな から 子どもまで みんな たのしめます。","underline":"おとな","options":["大人","太人","大入","太入"],"answer":"大人","note":"「おとな」寫成「大人」，是整個詞一起記的特殊讀法。「太」比「大」多一點，「入」和「人」撇捺的長短相反，都要看清楚。"},{"id":"ja-j-0056","level":1,"section":"moji","mondai":2,"stem":"うちの ちち は かいしゃいんです。","underline":"ちち","options":["母","兄","父","友"],"answer":"父","note":"「ちち」寫成「父」，指自己的父親。「母」是「はは」，「兄」是「あに」，「友」是「とも」。"},{"id":"ja-j-0057","level":1,"section":"moji","mondai":2,"stem":"はは は 学校の 先生です。","underline":"はは","options":["父","妹","母","友"],"answer":"母","note":"「はは」寫成「母」，指自己的母親。「父」是「ちち」，「妹」是「いもうと」，「友」是「とも」。"},{"id":"ja-j-0058","level":1,"section":"moji","mondai":2,"stem":"ごはんの まえに て を あらいます。","underline":"て","options":["千","毛","牛","手"],"answer":"手","note":"「て」寫成「手」。「千」「毛」「牛」都和「手」形近，但分別讀「せん」「け」「うし」。"},{"id":"ja-j-0059","level":1,"section":"moji","mondai":2,"stem":"ひと が おおぜい います。","underline":"ひと","options":["入","人","八","大"],"answer":"人","note":"「ひと」寫成「人」。「入」（はいる）和「人」撇捺的長短相反，最容易看錯；「八」「大」也是形近字。"},{"id":"ja-j-0060","level":1,"section":"moji","mondai":2,"stem":"おとこ の こが あそんで います。","underline":"おとこ","options":["文","田","力","男"],"answer":"男","note":"「おとこ」寫成「男」，上面是「田」、下面是「力」。單獨的「田」「力」只是「男」的一部分，「文」是不相干的字。"},{"id":"ja-j-0061","level":1,"section":"moji","mondai":2,"stem":"おんな の 学生が きました。","underline":"おんな","options":["母","安","女","好"],"answer":"女","note":"「おんな」寫成「女」。「好」「安」雖然都含有「女」，但是別的字；「母」是「はは」。"},{"id":"ja-j-0062","level":1,"section":"moji","mondai":2,"stem":"うちには こども が ふたり います。","underline":"こども","options":["子ども","字ども","小ども","子分"],"answer":"子ども","note":"「こども」寫成「子ども」。「字」和「子」形近，「小」和「子」讀音相近，但都組不成「こども」；「子分」讀「こぶん」，意思是手下。"},{"id":"ja-j-0063","level":1,"section":"moji","mondai":2,"stem":"にほん に すんで います。","underline":"にほん","options":["日本","月本","日木","月木"],"answer":"日本","note":"「にほん」寫成「日本」。「月」和「日」形近，「木」比「本」少一橫，「月本」「日木」「月木」都不是詞。"},{"id":"ja-j-0064","level":1,"section":"moji","mondai":2,"stem":"にほんご で 話します。","underline":"にほんご","options":["日本後","月本語","日本語","日本話"],"answer":"日本語","note":"「にほんご」寫成「日本語」，「語」表示語言。「日本後」把「語」換成同讀「ご」的「後」，「日本話」換成意思相近的「話」，「月本語」把「日」換成「月」。"},{"id":"ja-j-0065","level":1,"section":"moji","mondai":2,"stem":"がいこく で しごとを して います。","underline":"がいこく","options":["外国","内国","外校","外区"],"answer":"外国","note":"「がいこく」寫成「外国」。「内国」讀「ないこく」，意思相反；「外校」「外区」把「国」換成別的字，都不讀「がいこく」。"},{"id":"ja-j-0066","level":1,"section":"moji","mondai":2,"stem":"きょうは なんようび ですか。","underline":"なんようび","options":["木曜日","何曜日","火曜日","月曜日"],"answer":"何曜日","note":"「なんようび」寫成「何曜日」，用來問星期幾。「木曜日」「火曜日」「月曜日」分別是星期四、星期二、星期一。"},{"id":"ja-j-0067","level":1,"section":"moji","mondai":2,"stem":"きょうは かようび です。","underline":"かようび","options":["金曜日","火曜日","木曜日","水曜日"],"answer":"火曜日","note":"「かようび」寫成「火曜日」，是星期二。「金曜日」讀「きんようび」，「木曜日」讀「もくようび」，「水曜日」讀「すいようび」。"},{"id":"ja-j-0068","level":1,"section":"moji","mondai":2,"stem":"もくようび に テストが あります。","underline":"もくようび","options":["火曜日","水曜日","木曜日","金曜日"],"answer":"木曜日","note":"「もくようび」寫成「木曜日」，是星期四。「火曜日」「水曜日」「金曜日」分別讀「かようび」「すいようび」「きんようび」。"},{"id":"ja-j-0069","level":1,"section":"moji","mondai":2,"stem":"きょう は とても いい てんきです。","underline":"きょう","options":["今月","今年","今日","来日"],"answer":"今日","note":"「きょう」寫成「今日」。「今月」讀「こんげつ」，「今年」讀「ことし」，「来日」讀「らいにち」，意思是來日本。"},{"id":"ja-j-0070","level":1,"section":"moji","mondai":2,"stem":"らいねん だいがくに いきます。","underline":"らいねん","options":["毎年","今年","先年","来年"],"answer":"来年","note":"「らいねん」寫成「来年」，意思是明年。「毎年」讀「まいとし」，「今年」讀「ことし」，「先年」讀「せんねん」。"},{"id":"ja-j-0071","level":1,"section":"moji","mondai":2,"stem":"せんしゅう えいがを 見ました。","underline":"せんしゅう","options":["毎週","来週","今週","先週"],"answer":"先週","note":"「せんしゅう」寫成「先週」，意思是上週。「毎週」「来週」「今週」分別讀「まいしゅう」「らいしゅう」「こんしゅう」。"},{"id":"ja-j-0072","level":1,"section":"moji","mondai":2,"stem":"まいにち にほんごを 話します。","underline":"まいにち","options":["来日","毎日","今日","先日"],"answer":"毎日","note":"「まいにち」寫成「毎日」。「来日」讀「らいにち」，「今日」讀「きょう」，「先日」讀「せんじつ」。"},{"id":"ja-j-0073","level":1,"section":"moji","mondai":2,"stem":"ごぜん じゅうじに あいましょう。","underline":"ごぜん","options":["午前","午後","牛前","午先"],"answer":"午前","note":"「ごぜん」寫成「午前」。「午後」讀「ごご」；「牛前」的「牛」中間那一豎往上出頭，和「午」不同；「午先」不是詞。"},{"id":"ja-j-0074","level":1,"section":"moji","mondai":2,"stem":"ごご に 友だちが きます。","underline":"ごご","options":["午前","午後","午午","牛後"],"answer":"午後","note":"「ごご」寫成「午後」，兩個字都讀「ご」但字不同。「午前」讀「ごぜん」，「午午」不是詞，「牛後」的「牛」往上出頭，和「午」不同。"},{"id":"ja-j-0075","level":1,"section":"moji","mondai":2,"stem":"でんしゃ の なかで 本を 読みます。","underline":"でんしゃ","options":["田車","雨車","電東","電車"],"answer":"電車","note":"「でんしゃ」寫成「電車」。「雨」「田」和「電」的上下兩部分形近，「東」和「車」形近，組成的詞都不存在。"},{"id":"ja-j-0076","level":1,"section":"moji","mondai":2,"stem":"でんわ で 友だちと 話します。","underline":"でんわ","options":["電語","田話","田語","電話"],"answer":"電話","note":"「でんわ」寫成「電話」。「田」和「電」的下半部形近，「語」讀「ご」，「電語」「田話」「田語」都不是詞。"},{"id":"ja-j-0077","level":1,"section":"moji","mondai":2,"stem":"きのう くるま を 買いました。","underline":"くるま","options":["中","東","来","車"],"answer":"車","note":"「くるま」寫成「車」。「東」（ひがし）和「車」最容易看錯，「中」「来」讀法也完全不同。"},{"id":"ja-j-0078","level":1,"section":"moji","mondai":2,"stem":"がっこうへ いく みち で 友だちに あいました。","underline":"みち","options":["道","通","路","行"],"answer":"道","note":"「みち」寫成「道」。「通」用在「通る」（とおる），「行」用在「行く」（いく）；「路」平常只出現在「道路」這類複合詞，日常寫「みち」用「道」。"},{"id":"ja-j-0079","level":1,"section":"moji","mondai":2,"stem":"えき で 友だちと あいました。","underline":"えき","options":["駅","馬","駄","訳"],"answer":"駅","note":"「えき」寫成「駅」，左邊是馬字旁。「馬」只是「駅」的左半邊，「駄」是馬字旁的別的字，「訳」讀「やく」或「わけ」。"},{"id":"ja-j-0080","level":1,"section":"moji","mondai":2,"stem":"みせ は えきの まえに あります。","underline":"みせ","options":["占","居","庄","店"],"answer":"店","note":"「みせ」寫成「店」。「占」只是「店」裡面的部分，「居」「庄」是形近的別的字，都不讀「みせ」。"},{"id":"ja-j-0081","level":1,"section":"moji","mondai":2,"stem":"ばんごはんを いまから たべます。","underline":"たべます","options":["飯べます","飲べます","食べます","喫べます"],"answer":"食べます","note":"「たべます」寫成「食べます」。「飲」是「のむ」，「飯」是「ごはん」的「はん」，「喫」用在「喫茶店」，都不能接「べます」。"},{"id":"ja-j-0082","level":1,"section":"moji","mondai":2,"stem":"パーティーで ジュースを のみます。","underline":"のみます","options":["飯みます","食みます","飲みます","飼みます"],"answer":"飲みます","note":"「のみます」寫成「飲みます」。「飯」「食」「飼」和「飲」一樣有食字旁，但「食」要接「べます」、「飼」要接「います」，都不讀「のみます」。"},{"id":"ja-j-0083","level":1,"section":"moji","mondai":2,"stem":"ニュースを テレビで みます。","underline":"みます","options":["視ます","目ます","見ます","看ます"],"answer":"見ます","note":"「みます」寫成「見ます」，看電視、看新聞都用它。「目ます」不是詞；「視」「看」的「みる」不是常用寫法，「看る」還專指照顧病人。"},{"id":"ja-j-0084","level":1,"section":"moji","mondai":2,"stem":"おんがくを ききます。","underline":"ききます","options":["効きます","聞きます","利きます","問きます"],"answer":"聞きます","note":"「ききます」寫成「聞きます」，聽音樂的意思。「効きます」是有效果，「利きます」是起作用，雖然也讀「ききます」但意思不合；「問」讀「とう」，不接「きます」。"},{"id":"ja-j-0085","level":1,"section":"moji","mondai":2,"stem":"にほんごで はなします。","underline":"はなします","options":["離します","放します","話します","講します"],"answer":"話します","note":"「はなします」寫成「話します」，說話的意思。「離します」是分開，「放します」是放手，雖然也讀「はなします」但意思不合；「講します」不是詞。"},{"id":"ja-j-0086","level":1,"section":"moji","mondai":2,"stem":"まいばん 本を よみます。","underline":"よみます","options":["話みます","読みます","訳みます","語みます"],"answer":"読みます","note":"「よみます」寫成「読みます」，左邊是言字旁。「話」「語」「訳」也都是言字旁，但分別讀「はなす」「かたる」「やく」，不能接「みます」。"},{"id":"ja-j-0087","level":1,"section":"moji","mondai":2,"stem":"てがみを かきます。","underline":"かきます","options":["描きます","書きます","画きます","欠きます"],"answer":"書きます","note":"「かきます」寫成「書きます」，寫信、寫字都用它。「描きます」「画きます」指畫圖，「欠きます」是缺少，雖然也讀「かきます」，都不能用在寫信。"},{"id":"ja-j-0088","level":1,"section":"moji","mondai":2,"stem":"あした 友だちが いえに きます。","underline":"きます","options":["来ます","起ます","着ます","切ます"],"answer":"来ます","note":"「きます」寫成「来ます」，來的意思。「着ます」是穿衣服，雖然也讀「きます」但意思不合；「起」「切」要寫成「起きます」「切ります」，沒有「起ます」「切ます」。"},{"id":"ja-j-0089","level":1,"section":"moji","mondai":2,"stem":"まいあさ 八時に がっこうへ いきます。","underline":"いきます","options":["生きます","行きます","帰きます","入きます"],"answer":"行きます","note":"「いきます」寫成「行きます」，去的意思。「生きます」是活著，雖然也讀「いきます」但意思不合；「帰」讀「かえる」，「入」讀「はいる」。"},{"id":"ja-j-0090","level":1,"section":"moji","mondai":2,"stem":"まいあさ 七時に いえを でます。","underline":"でます","options":["出ます","入ます","立ます","来ます"],"answer":"出ます","note":"「でます」寫成「出ます」，「いえを でます」是出門。「入」是進入、寫成「入ります」，「立」要寫成「立ちます」，「来ます」讀「きます」。"},{"id":"ja-j-0091","level":1,"section":"moji","mondai":2,"stem":"ねる まえに おふろに はいります。","underline":"はいります","options":["立ります","出ります","入ります","切ります"],"answer":"入ります","note":"「はいります」寫成「入ります」，「おふろに はいります」是洗澡。「立」讀「たつ」，「出」讀「でる」，「切ります」讀「きります」，都不讀「はいります」。"},{"id":"ja-j-0092","level":1,"section":"moji","mondai":2,"stem":"先生が きょうしつに 来たので、学生が たちます。","underline":"たちます","options":["立ちます","起ちます","経ちます","建ちます"],"answer":"立ちます","note":"「たちます」寫成「立ちます」，站起來的意思。「建ちます」是建築物蓋好，「経ちます」是時間經過，意思都不合；「起」的常用讀法是「おきる」，日常不寫成「起ちます」。"},{"id":"ja-j-0093","level":1,"section":"moji","mondai":2,"stem":"つかれたから すこし やすみます。","underline":"やすみます","options":["体みます","休みます","安みます","寄みます"],"answer":"休みます","note":"「やすみます」寫成「休みます」，人字旁加「木」。「体」和「休」只差一橫，最容易看錯；「安」用在「安い」，「寄」讀「よる」，都不能接「みます」。"},{"id":"ja-j-0094","level":1,"section":"moji","mondai":2,"stem":"先生が なまえを いいます。","underline":"いいます","options":["試います","話います","言います","議います"],"answer":"言います","note":"「いいます」寫成「言います」。「話」「試」「議」雖然都有言字旁，但分別讀「はなす」「ためす」「ぎ」，接上「います」都不成詞。"},{"id":"ja-j-0095","level":1,"section":"moji","mondai":2,"stem":"みせで やさいを かいます。","underline":"かいます","options":["飼います","買います","替います","換います"],"answer":"買います","note":"「かいます」寫成「買います」，買東西的意思。「飼います」是養動物，雖然也讀「かいます」但意思不合；「替」「換」讀「かえる」，不能接「います」。"},{"id":"ja-j-0096","level":1,"section":"moji","mondai":2,"stem":"この とけいは とても たかい です。","underline":"たかい","options":["多い","長い","古い","高い"],"answer":"高い","note":"「たかい」寫成「高い」，這裡是價錢貴。「多い」讀「おおい」，「長い」讀「ながい」，「古い」讀「ふるい」。"},{"id":"ja-j-0097","level":1,"section":"moji","mondai":2,"stem":"この レストランは やすい です。","underline":"やすい","options":["寄い","易い","休い","安い"],"answer":"安い","note":"「やすい」寫成「安い」，便宜的意思。「易い」雖然也能讀「やすい」，但意思是容易，不能形容餐廳便宜；「寄」「休」不能接「い」當形容詞。"},{"id":"ja-j-0098","level":1,"section":"moji","mondai":2,"stem":"この かわは とても ながい です。","underline":"ながい","options":["永い","長い","強い","高い"],"answer":"長い","note":"「ながい」寫成「長い」，形容河很長。「永い」也讀「ながい」，但指時間久遠，不用來說河的長度；「強い」讀「つよい」，「高い」讀「たかい」。"},{"id":"ja-j-0099","level":1,"section":"moji","mondai":2,"stem":"しろい ねこが います。","underline":"しろい","options":["白い","百い","自い","旧い"],"answer":"白い","note":"「しろい」寫成「白い」。「百」「自」和「白」只差一筆，最容易看錯；「旧」是舊的意思，都不讀「しろい」。"},{"id":"ja-j-0100","level":1,"section":"moji","mondai":2,"stem":"なまえ を ここに かいて ください。","underline":"なまえ","options":["名前","名先","友前","名間"],"answer":"名前","note":"「なまえ」寫成「名前」。「名先」把「前」換成「先」，「友前」把「名」換成「友」，「名間」也不是詞。"},{"id":"ja-j-0101","level":1,"section":"goi","mondai":3,"stem":"まいあさ コーヒーを （　　）。","underline":null,"options":["たべます","みます","ききます","のみます"],"answer":"のみます","note":"「コーヒー」是喝的東西，動詞要用「のみます」。「たべます」用在固體食物，「みます」「ききます」放進來句意不通。"},{"id":"ja-j-0102","level":1,"section":"goi","mondai":3,"stem":"ばんごはんを （　　） から、テレビを 見ます。","underline":null,"options":["のんで","きいて","かいて","たべて"],"answer":"たべて","note":"「ばんごはんを たべてから」是「吃完晚餐之後」，接著看電視，順序最自然。「のんで」用在飲料，「かいて」（寫）、「きいて」（聽）都不能接「ばんごはん」。"},{"id":"ja-j-0103","level":1,"section":"goi","mondai":3,"stem":"新しい ノートを （　　）。","underline":null,"options":["ききました","たべました","のみました","かいました"],"answer":"かいました","note":"「新しい ノートを かいました」是「買了新筆記本」，寫成漢字是「買いました」；「書きました」要念「かきました」。其他三個動詞都不能接筆記本。"},{"id":"ja-j-0104","level":1,"section":"goi","mondai":3,"stem":"きのう 友だちに （　　）。","underline":null,"options":["かいました","たちました","しました","あいました"],"answer":"あいました","note":"「友だちに あいました」是「見到朋友」，「あう」的對象用「に」標示。「かいました」「たちました」「しました」都不能這樣接「友だちに」。"},{"id":"ja-j-0105","level":1,"section":"goi","mondai":3,"stem":"つかれましたから、いえで （　　）。","underline":null,"options":["はたらきます","やすみます","はしります","およぎます"],"answer":"やすみます","note":"前半句「つかれましたから」（因為累了）說明原因，後面自然是在家休息，選「やすみます」。「はたらきます」（工作）、「はしります」（跑）、「およぎます」（游泳）都跟疲累的理由對不上。"},{"id":"ja-j-0106","level":1,"section":"goi","mondai":3,"stem":"あした こうえんへ さんぽに （　　）。","underline":null,"options":["きます","いきます","はいります","かえります"],"answer":"いきます","note":"「さんぽに いきます」是「去散步」，「〜に いく」表示去做某事。「きます」以說話者所在地為終點，從別處說要去公園不用「きます」；「はいります」「かえります」放進來句意不通。"},{"id":"ja-j-0107","level":1,"section":"goi","mondai":3,"stem":"たなかさんは いま 学校に （　　）。","underline":null,"options":["かいます","あります","もちます","います"],"answer":"います","note":"人或動物的存在用「います」，物品才用「あります」，所以是「たなかさんは 学校に います」。「かいます」「もちます」放進來句意不通。"},{"id":"ja-j-0108","level":1,"section":"goi","mondai":3,"stem":"つくえの 上に 本が （　　）。","underline":null,"options":["でます","います","たちます","あります"],"answer":"あります","note":"書是物品，存在要用「あります」。「います」用在人和動物，是最容易混淆的錯誤選項。"},{"id":"ja-j-0109","level":1,"section":"goi","mondai":3,"stem":"きょうは てんきが （　　）。","underline":null,"options":["たかいです","ながいです","やすいです","いいです"],"answer":"いいです","note":"「てんきが いい」是「天氣好」的固定說法。「たかい」「ながい」「やすい」都不能形容天氣。"},{"id":"ja-j-0110","level":1,"section":"goi","mondai":3,"stem":"その 本は とても （　　）。","underline":null,"options":["おいしいです","うるさいです","おもしろいです","はやいです"],"answer":"おもしろいです","note":"形容書的內容要用「おもしろい」（有趣）。「おいしい」用在食物，「うるさい」（吵）、「はやい」（快）都不適合形容一本書。"},{"id":"ja-j-0111","level":1,"section":"goi","mondai":3,"stem":"この りんごは あまいですから、（　　）。","underline":null,"options":["おもしろいです","からいです","あおいです","おいしいです"],"answer":"おいしいです","note":"「あまいですから」（因為很甜）說明理由，結論是「おいしいです」（好吃）。「からいです」（辣）跟甜互相矛盾，「あおいです」「おもしろいです」也不能由甜推出來。"},{"id":"ja-j-0112","level":1,"section":"goi","mondai":3,"stem":"すみませんが、もう いちど （　　） ください。","underline":null,"options":["たべて","ねて","はなして","のんで"],"answer":"はなして","note":"「もう いちど はなして ください」是請對方「再說一次」，常用在沒聽清楚的時候。「たべて」「のんで」「ねて」放進來都不是自然的請求。"},{"id":"ja-j-0113","level":1,"section":"goi","mondai":3,"stem":"いえへ かえる まえに、ぎんこうへ （　　）。","underline":null,"options":["いきました","のみました","たべました","ききました"],"answer":"いきました","note":"「ぎんこうへ いきました」是「去了銀行」，「へ」標示移動的方向，要接移動動詞。「のみました」「たべました」「ききました」都不能接「ぎんこうへ」。"},{"id":"ja-j-0114","level":1,"section":"goi","mondai":3,"stem":"らいねんから 大学で にほんごを （　　）。","underline":null,"options":["あいます","はしります","べんきょうします","やすみます"],"answer":"べんきょうします","note":"「にほんごを べんきょうします」是「學日文」。「あいます」「はしります」「やすみます」都不能拿語言當受詞。"},{"id":"ja-j-0115","level":1,"section":"goi","mondai":3,"stem":"しゅくだいが おわってから、テレビを （　　）。","underline":null,"options":["みます","ききます","のみます","ねます"],"answer":"みます","note":"電視要用「みます」（看）。「ききます」對電視不自然，「のみます」「ねます」更不能接「テレビを」。"},{"id":"ja-j-0116","level":1,"section":"goi","mondai":3,"stem":"おんがくを （　　） のが すきです。","underline":null,"options":["みる","かく","きく","のむ"],"answer":"きく","note":"音樂要用「きく」（聽）。「みる」「かく」「のむ」都不能接「おんがくを」。"},{"id":"ja-j-0117","level":1,"section":"goi","mondai":3,"stem":"あさごはんに パンを 二まい （　　）。","underline":null,"options":["たべました","のみました","ききました","はなしました"],"answer":"たべました","note":"「パンを たべました」是「吃了麵包」，「二まい」是數片狀物的量詞。「のみました」用在飲料，「ききました」「はなしました」不能接麵包。"},{"id":"ja-j-0118","level":1,"section":"goi","mondai":3,"stem":"つめたい 水を （　　）。","underline":null,"options":["よみました","ききました","のみました","たべました"],"answer":"のみました","note":"「水を のみました」是「喝了水」。「たべました」用在固體食物，「ききました」「よみました」不能接水。"},{"id":"ja-j-0119","level":1,"section":"goi","mondai":3,"stem":"きのうは しごとが とても （　　）。","underline":null,"options":["つよいでした","いそがしかったです","はやいです","つかれます"],"answer":"いそがしかったです","note":"「きのうは」說的是過去，「いそがしい」的過去式是「いそがしかったです」。「つよいでした」是形容詞過去式的錯誤活用，「はやいです」時態不對，「しごとが つかれます」也不是自然的說法。"},{"id":"ja-j-0120","level":1,"section":"goi","mondai":3,"stem":"子どもが こうえんで （　　） います。","underline":null,"options":["あそんで","はたらいて","あいて","しまって"],"answer":"あそんで","note":"「こうえんで あそんで います」是「在公園玩」。小孩在公園「はたらいて」（工作）不合常理，「あいて」「しまって」放進來句意不通。"},{"id":"ja-j-0121","level":1,"section":"goi","mondai":3,"stem":"ほんが つくえの （　　）から おちました。","underline":null,"options":["うえ","した","まえ","うしろ"],"answer":"うえ","note":"書是「從桌上掉下來」，選「うえ」。從桌子的「した」（下面）、「まえ」（前面）、「うしろ」（後面）都不會掉落。"},{"id":"ja-j-0122","level":1,"section":"goi","mondai":3,"stem":"その みせは えきの （　　） に あります。","underline":null,"options":["たかい","ながい","ちかく","つよい"],"answer":"ちかく","note":"「えきの ちかく」是「車站附近」，「ちかく」在這裡當名詞用，後面可以接「に」。「たかい」「ながい」「つよい」是形容詞，不能放在「えきの」後面當地點。"},{"id":"ja-j-0123","level":1,"section":"goi","mondai":3,"stem":"私の いえは ここから とても （　　） です。","underline":null,"options":["あつい","とおい","ふるい","きれい"],"answer":"とおい","note":"「ここから とおい」是「離這裡很遠」，「から」表示距離的起點。「あつい」「ふるい」「きれい」都不是描述距離的詞。"},{"id":"ja-j-0124","level":1,"section":"goi","mondai":3,"stem":"きょうは あついから、まどを （　　） ください。","underline":null,"options":["しめて","あけて","けして","つけて"],"answer":"あけて","note":"因為很熱，所以請對方開窗，選「あけて」。「しめて」（關）跟理由相反；「けして」「つけて」是關、開電器的說法，不用在窗戶上。"},{"id":"ja-j-0125","level":1,"section":"goi","mondai":3,"stem":"ねる まえに でんきを （　　） ください。","underline":null,"options":["あけて","しめて","けして","のんで"],"answer":"けして","note":"睡前請對方關燈，電燈要用「けす」。「あけて」「しめて」是開關門窗的說法，「のんで」不能接電燈。"},{"id":"ja-j-0126","level":1,"section":"goi","mondai":3,"stem":"くらいですから、でんきを （　　） ください。","underline":null,"options":["けして","つけて","しめて","あけて"],"answer":"つけて","note":"因為很暗，所以請對方開燈，電燈要用「つける」。「けして」（關）跟理由相反，「しめて」「あけて」用在門窗。"},{"id":"ja-j-0127","level":1,"section":"goi","mondai":3,"stem":"つぎの （　　） を 右に まがって ください。","underline":null,"options":["かど","やま","はし","かわ"],"answer":"かど","note":"「かどを 右に まがる」是「在轉角右轉」。「やま」「はし」「かわ」都不是可以轉彎的地方。"},{"id":"ja-j-0128","level":1,"section":"goi","mondai":3,"stem":"毎日 ちかてつで （　　） まで いきます。","underline":null,"options":["みず","かわ","みち","かいしゃ"],"answer":"かいしゃ","note":"每天搭地下鐵去的地方，最合理的是「かいしゃ」（公司）。「みず」（水）不是地點，「かわ」「みち」也不是通勤的目的地。"},{"id":"ja-j-0129","level":1,"section":"goi","mondai":3,"stem":"ふゆに なりました。 きょうは （　　） が ふって います。 とても さむいです。","underline":null,"options":["かぜ","はる","はな","ゆき"],"answer":"ゆき","note":"冬天、很冷，又是「ふって います」（正在下），只有「ゆき」（雪）合適。「かぜ」（風）不用「ふる」，「はる」「はな」放進來句意不通。"},{"id":"ja-j-0130","level":1,"section":"goi","mondai":3,"stem":"きのう 友だちと （　　） を 見に いきました。","underline":null,"options":["ほん","でんわ","しんぶん","えいが"],"answer":"えいが","note":"「えいがを 見に いく」是「去看電影」。「ほん」「しんぶん」要用「よむ」，「でんわ」也不是去看的東西。"},{"id":"ja-j-0131","level":1,"section":"goi","mondai":3,"stem":"たんじょうびに 友だちから （　　） を もらいました。","underline":null,"options":["しゅくだい","プレゼント","ニュース","しごと"],"answer":"プレゼント","note":"生日從朋友那裡收到的，最合理的是「プレゼント」（禮物）。「しゅくだい」「ニュース」「しごと」都不是生日會收到的東西。"},{"id":"ja-j-0132","level":1,"section":"goi","mondai":3,"stem":"ねこは いすの 下で （　　） います。","underline":null,"options":["はしって","ねて","はたらいて","かって"],"answer":"ねて","note":"貓在椅子底下「ねて います」（睡覺）。在椅子下「はしって」（跑）不自然，「はたらいて」「かって」用在貓身上句意不通。"},{"id":"ja-j-0133","level":1,"section":"goi","mondai":3,"stem":"つかれましたから、（　　） すわりました。","underline":null,"options":["すぐ","もう","まだ","ぜんぜん"],"answer":"すぐ","note":"因為累了，所以「すぐ すわりました」（馬上坐下）。「まだ」「ぜんぜん」在這裡要接否定，「もう すわりました」（已經坐了）跟「因為累了」的因果接不起來。"},{"id":"ja-j-0134","level":1,"section":"goi","mondai":3,"stem":"しゅくだいが むずかしくて、 （　　） わかりませんでした。","underline":null,"options":["ぜんぜん","たくさん","すぐ","とても"],"answer":"ぜんぜん","note":"「ぜんぜん」接否定表示「完全不」，「ぜんぜん わかりませんでした」是「完全不懂」。「たくさん」「すぐ」放進來不通；「とても」在 N5 是修飾肯定的「很」，不用來表示「完全不」。"},{"id":"ja-j-0135","level":1,"section":"goi","mondai":3,"stem":"A: あした パーティーに 来ますか。 B: はい、（　　） 行きます。","underline":null,"options":["たくさん","すぐ","まだ","もちろん"],"answer":"もちろん","note":"回答「はい」之後加「もちろん」（當然），表示一定會去。「たくさん」「まだ」放進來不通，明天的派對也不會說「すぐ 行きます」（馬上去）。"},{"id":"ja-j-0136","level":1,"section":"goi","mondai":3,"stem":"おかねが ありませんから、何も （　　）。","underline":null,"options":["かいません","たべました","のみました","ききました"],"answer":"かいません","note":"「何も」後面要接否定，表示「什麼都不」；前面又說沒錢，所以是「何も かいません」（什麼都不買）。其他三個都是肯定形，不能接「何も」。"},{"id":"ja-j-0137","level":1,"section":"goi","mondai":3,"stem":"私の おとうとは 大学生では （　　）。 高校生です。","underline":null,"options":["ありません","ありました","あります","ありませんでした"],"answer":"ありません","note":"後句說「高校生です」，所以前面是現在式的否定「大学生では ありません」。「ありませんでした」是過去式，跟後句的現在式對不上；「あります」「ありました」是肯定，跟後句矛盾。"},{"id":"ja-j-0138","level":1,"section":"goi","mondai":3,"stem":"その へやには 子どもが 三（　　） います。","underline":null,"options":["まい","ほん","にん","つ"],"answer":"にん","note":"數人用「にん」，「三にん」念「さんにん」。「まい」數紙張等薄平的東西，「ほん」數細長物，「つ」不用來數人。"},{"id":"ja-j-0139","level":1,"section":"goi","mondai":3,"stem":"きょうしつには ボールが 五（　　） あります。","underline":null,"options":["にん","つ","まい","ほん"],"answer":"つ","note":"「つ」是數小東西的通用量詞，「五つ」念「いつつ」。「にん」數人，「まい」數薄平的東西，「ほん」數細長物，都不適合數球。"},{"id":"ja-j-0140","level":1,"section":"goi","mondai":3,"stem":"ペンを 二（　　） 買いました。","underline":null,"options":["さつ","ほん","にん","まい"],"answer":"ほん","note":"筆是細長的東西，用「ほん」數，「二ほん」念「にほん」。「さつ」數書本，「にん」數人，「まい」數薄平的東西。"},{"id":"ja-j-0141","level":1,"section":"goi","mondai":3,"stem":"きってを 三（　　） ください。","underline":null,"options":["ほん","にん","まい","つ"],"answer":"まい","note":"郵票是薄平的東西，用「まい」數，「三まい」念「さんまい」。「ほん」數細長物，「にん」數人；「つ」雖然是通用量詞，數郵票一般還是說「まい」。"},{"id":"ja-j-0142","level":1,"section":"goi","mondai":3,"stem":"しごとは いつも （　　） おわります。","underline":null,"options":["なんじで","たかい","ちかい","はやく"],"answer":"はやく","note":"修飾動詞「おわります」要用副詞「はやく」（早早地）。「たかい」「ちかい」是形容詞原形，不能直接修飾動詞；「なんじで」放進來不成句。"},{"id":"ja-j-0143","level":1,"section":"goi","mondai":3,"stem":"私の いえから 駅まで （　　） 十分です。","underline":null,"options":["はやい","ちかい","あるいて","たかい"],"answer":"あるいて","note":"「あるいて 十分」是「走路十分鐘」，用「て形」表示移動方式。「はやい」「ちかい」「たかい」放在「十分です」前面都不成句。"},{"id":"ja-j-0144","level":1,"section":"goi","mondai":3,"stem":"きょうは あめが ふって いるから、（　　） を もって きました。","underline":null,"options":["かばん","めがね","ぼうし","かさ"],"answer":"かさ","note":"下雨天帶的是「かさ」（傘）。「かばん」「めがね」「ぼうし」都跟下雨這個理由對不上。"},{"id":"ja-j-0145","level":1,"section":"goi","mondai":3,"stem":"さむいですから、（　　） を きて ください。","underline":null,"options":["ぼうし","かばん","コート","パジャマ"],"answer":"コート","note":"因為冷而「きる」（穿）的是「コート」（外套）。「ぼうし」要用「かぶる」，「かばん」不是穿的，「パジャマ」是睡衣，不是禦寒的衣物。"},{"id":"ja-j-0146","level":1,"section":"goi","mondai":3,"stem":"すみません、この みちは よく わかりません。 ちずを （　　） ください。","underline":null,"options":["みせて","のんで","たべて","かって"],"answer":"みせて","note":"不認得路，所以請對方「ちずを みせて ください」（給我看地圖）。「のんで」「たべて」不能接地圖，「かって」（買）也不是向人問路時會提的請求。"},{"id":"ja-j-0147","level":1,"section":"goi","mondai":3,"stem":"私は にほんへ いった ことが （　　）。","underline":null,"options":["あります","します","なります","います"],"answer":"あります","note":"「〜た ことが あります」是表示經驗的固定句型「曾經…過」。「します」「なります」「います」都不能接在「ことが」後面表示經驗。"},{"id":"ja-j-0148","level":1,"section":"goi","mondai":3,"stem":"来年 大学へ （　　） つもりです。","underline":null,"options":["いく","でる","かえる","すむ"],"answer":"いく","note":"「大学へ いく」是「去上大學」，「へ」標示方向。「でる」（離開）方向相反，「かえる」是回到原處，「すむ」要用「に」而不是「へ」。"},{"id":"ja-j-0149","level":1,"section":"goi","mondai":3,"stem":"くつを （　　）から、いえに 入って ください。","underline":null,"options":["ぬいで","あけて","しめて","はいて"],"answer":"ぬいで","note":"進日本的家之前要「くつを ぬぐ」（脫鞋）。「はいて」（穿）意思相反，「あけて」「しめて」不能用在鞋子上。"},{"id":"ja-j-0150","level":1,"section":"goi","mondai":3,"stem":"たろうさんは おとうさん（　　） せが たかいです。","underline":null,"options":["が","より","の","に"],"answer":"より","note":"「A は B より 〜」是比較句型「A 比 B 更…」，所以是太郎比爸爸高。「が」「の」「に」放進來都不是比較的說法。"},{"id":"ja-j-0151","level":1,"section":"goi","mondai":4,"stem":"わたしの ちちは びょういんで びょうきの 人を みて います。","underline":null,"options":["わたしの ちちは ははと はたらいて います。","わたしの ちちは いしゃです。","わたしの ちちは びょうきです。","わたしの ちちは 学校の 先生です。"],"answer":"わたしの ちちは いしゃです。","note":"在醫院「びょうきの 人を みる」（看病人）的是醫生，所以是「ちちは いしゃです」。「びょうきです」變成爸爸自己生病，是最容易選錯的選項；「学校の 先生」工作地點不對。"},{"id":"ja-j-0152","level":1,"section":"goi","mondai":4,"stem":"この りょうりは おいしくないです。","underline":null,"options":["この りょうりは おいしいです。","この りょうりは あまいです。","この りょうりは まずいです。","この りょうりは すきです。"],"answer":"この りょうりは まずいです。","note":"「おいしくない」（不好吃）就是「まずい」（難吃）。「おいしいです」意思相反，「あまいです」「すきです」說的是味道和喜好，不是好不好吃。"},{"id":"ja-j-0153","level":1,"section":"goi","mondai":4,"stem":"たなかさんは えいごを おしえて います。","underline":null,"options":["たなかさんは えいごの 学生です。","たなかさんは アメリカ人です。","たなかさんは えいごを ならって います。","たなかさんは えいごの 先生です。"],"answer":"たなかさんは えいごの 先生です。","note":"「えいごを おしえて いる」（在教英文）就是「えいごの 先生」（英文老師）。「えいごを ならって いる」是在學英文，教與學的立場相反，最容易選錯。"},{"id":"ja-j-0154","level":1,"section":"goi","mondai":4,"stem":"わたしは まいにち 七時に おきます。","underline":null,"options":["わたしは よる 七時に おきます。","わたしは あさ 七時に ねます。","わたしは あさ 七時に おきます。","わたしは よる 七時に ねます。"],"answer":"わたしは あさ 七時に おきます。","note":"七點起床一般是指早上七點，所以換成「あさ 七時に おきます」。「よる 七時に おきます」時間不對，另外兩個把「おきる」（起床）換成「ねる」（睡覺），意思完全不同。"},{"id":"ja-j-0155","level":1,"section":"goi","mondai":4,"stem":"しゅくだいは ぜんぶ おわりました。","underline":null,"options":["しゅくだいが すこし のこって います。","しゅくだいは まだ ありません。","しゅくだいは ぜんぶ しました。","しゅくだいは ぜんぜん しません でした。"],"answer":"しゅくだいは ぜんぶ しました。","note":"「ぜんぶ おわりました」（全部做完了）就是「ぜんぶ しました」（全部做了）。「すこし のこって います」表示還剩一點，跟「ぜんぶ」矛盾。"},{"id":"ja-j-0156","level":1,"section":"goi","mondai":4,"stem":"あの レストランは とても 高いです。","underline":null,"options":["あの レストランは やすいです。","あの レストランは たかい たてものです。","あの レストランは ひろいです。","あの レストランは おかねが たくさん いります。"],"answer":"あの レストランは おかねが たくさん いります。","note":"「とても 高い」（很貴）就是去吃要花很多錢，所以是「おかねが たくさん いります」。「たかい たてもの」的「たかい」是「高」的意思，同一個詞但意思不同，最容易選錯。"},{"id":"ja-j-0157","level":1,"section":"goi","mondai":4,"stem":"わたしは くだものが 大すきです。","underline":null,"options":["わたしは くだものが すきじゃ ありません。","わたしは くだものが きらいです。","わたしは くだものを たべません。","わたしは くだものを よく たべます。"],"answer":"わたしは くだものを よく たべます。","note":"「大すき」（非常喜歡）水果，所以會「よく たべます」（常吃）。「すきじゃ ありません」「きらいです」「たべません」都是相反的意思。"},{"id":"ja-j-0158","level":1,"section":"goi","mondai":4,"stem":"きのうの よる、はやく ベッドに 入りました。","underline":null,"options":["きのう おそく ねました。","きのう はやく ねました。","きのうの あさ、おそく おきました。","きのうの あさ、はやく おきました。"],"answer":"きのう はやく ねました。","note":"「ベッドに 入る」（上床）就是「ねる」（睡覺），「はやく ベッドに 入りました」等於「はやく ねました」。「おそく ねました」早晚相反，後兩個選項把晚上睡覺換成早上起床。"},{"id":"ja-j-0159","level":1,"section":"goi","mondai":4,"stem":"にちようびは ひまです。","underline":null,"options":["にちようびは いそがしいです。","にちようびは しごとが あります。","にちようびは じかんが あります。","にちようびは つかれて います。"],"answer":"にちようびは じかんが あります。","note":"「ひま」（有空）就是「じかんが あります」（有時間）。「いそがしい」意思相反，「しごとが あります」也表示沒空。"},{"id":"ja-j-0160","level":1,"section":"goi","mondai":4,"stem":"きょうしつに 学生が おおぜい います。","underline":null,"options":["きょうしつには 学生が ぜんぜん いません。","きょうしつには 学生が たくさん います。","きょうしつには 学生が 一人 います。","きょうしつには 学生が 二人 います。"],"answer":"きょうしつには 学生が たくさん います。","note":"「おおぜい」和「たくさん」都是「很多」，「おおぜい」只用在人身上。「ぜんぜん いません」意思相反，「一人」「二人」都不算很多。"},{"id":"ja-j-0161","level":1,"section":"goi","mondai":4,"stem":"わたしは いま おなかが すいて います。","underline":null,"options":["わたしは いま 何か たべたいです。","わたしは いま 何か のみたいです。","わたしは いま ねたいです。","わたしは いま やすみたいです。"],"answer":"わたしは いま 何か たべたいです。","note":"「おなかが すいて いる」（肚子餓）就是想吃點東西，選「たべたいです」。「のみたいです」是口渴，「ねたい」「やすみたい」是累，跟肚子餓無關。"},{"id":"ja-j-0162","level":1,"section":"goi","mondai":4,"stem":"でんしゃの 中で 本を 読みました。","underline":null,"options":["でんしゃで 本を かいました。","でんしゃに のる まえに 本を 読みました。","でんしゃに のって いる あいだに 本を 読みました。","でんしゃの まえで 本を 読みました。"],"answer":"でんしゃに のって いる あいだに 本を 読みました。","note":"「でんしゃの 中で」（在電車裡）讀書，就是搭電車的時候讀書。「のる まえに」（上車前）時間不對，「でんしゃの まえで」（在電車前面）地點不對。"},{"id":"ja-j-0163","level":1,"section":"goi","mondai":4,"stem":"わたしの いえは 駅から とおく ありません。","underline":null,"options":["わたしの いえは 駅から とても とおいです。","わたしの いえは 駅の 中に あります。","わたしの いえは 駅の 上に あります。","わたしの いえは 駅から ちかいです。"],"answer":"わたしの いえは 駅から ちかいです。","note":"「とおく ありません」（不遠）就是「ちかいです」（近）。「とても とおいです」意思相反，「駅の 中」「駅の 上」說的是房子在車站裡面、上面，不是距離。"},{"id":"ja-j-0164","level":1,"section":"goi","mondai":4,"stem":"たなかさんは じょうずに ピアノを ひきます。","underline":null,"options":["たなかさんは ピアノが へたです。","たなかさんは ピアノを はじめて ひきます。","たなかさんは ピアノが きらいです。","たなかさんは ピアノを ひくのが じょうずです。"],"answer":"たなかさんは ピアノを ひくのが じょうずです。","note":"「じょうずに ひきます」（彈得很好）可以換成「ひくのが じょうずです」（擅長彈），只是句型不同。「へたです」意思相反，「はじめて ひきます」是第一次彈。"},{"id":"ja-j-0165","level":1,"section":"goi","mondai":4,"stem":"もう おそいから、いえに かえりましょう。","underline":null,"options":["もう はやいから、もう少し いましょう。","しごとが はやく おわったから、かえりましょう。","じかんが おそく なったから、いえに かえりましょう。","もう おそいから、ねましょう。"],"answer":"じかんが おそく なったから、いえに かえりましょう。","note":"「もう おそい」（已經很晚了）等於「じかんが おそく なった」。「もう おそいから、ねましょう」理由相同，但提議的是去睡覺而不是回家，最容易選錯。"},{"id":"ja-j-0166","level":1,"section":"goi","mondai":4,"stem":"その みせは くだものを うって います。","underline":null,"options":["その みせは くだものを かいます。","その みせは くだものが すきです。","その みせは くだものの みせです。","その みせは くだものを たべます。"],"answer":"その みせは くだものの みせです。","note":"「くだものを うって いる」（在賣水果）的店就是「くだものの みせ」（水果店）。「かいます」（買）是客人的立場，跟「うる」（賣）相反。"},{"id":"ja-j-0167","level":1,"section":"goi","mondai":4,"stem":"きのう びょうきで 学校を やすみました。","underline":null,"options":["きのうは げんきでした。","きのうは 学校に いきませんでした。","きのうは 学校で べんきょうしました。","きのうは よる おそくまで 学校に いました。"],"answer":"きのうは 学校に いきませんでした。","note":"「学校を やすむ」是「沒去上學」，所以等於「学校に いきませんでした」。「学校で べんきょうしました」表示有去學校，「げんきでした」跟生病矛盾。"},{"id":"ja-j-0168","level":1,"section":"goi","mondai":4,"stem":"だれも きょうしつに いません。","underline":null,"options":["きょうしつに 人が いません。","きょうしつに 一人 います。","きょうしつに 二人 います。","きょうしつに 学生が おおぜい います。"],"answer":"きょうしつに 人が いません。","note":"「だれも いません」（誰都不在）就是「人が いません」（沒有人）。「一人 います」「二人 います」「おおぜい います」都表示有人在。"},{"id":"ja-j-0169","level":1,"section":"goi","mondai":4,"stem":"しゅくだいは まだ おわって いません。","underline":null,"options":["しゅくだいは ぜんぶ おわりました。","しゅくだいは まだ のこって います。","しゅくだいは あしたから します。","しゅくだいは ありません。"],"answer":"しゅくだいは まだ のこって います。","note":"「まだ おわって いません」（還沒做完）就是作業「まだ のこって います」（還剩著）。「ぜんぶ おわりました」意思相反，「ありません」表示根本沒有作業。"},{"id":"ja-j-0170","level":1,"section":"goi","mondai":4,"stem":"たろうさんは スポーツが すきで、 まいにち します。","underline":null,"options":["たろうさんは スポーツを よく します。","たろうさんは スポーツを 見ません。","たろうさんは スポーツを ぜんぜん しません。","たろうさんは スポーツが きらいです。"],"answer":"たろうさんは スポーツを よく します。","note":"喜歡運動而且「まいにち します」（每天做），就是「よく します」（常做）。「見ません」「ぜんぜん しません」「きらいです」都跟題面相反。"},{"id":"ja-j-0171","level":1,"section":"goi","mondai":4,"stem":"きょうしつは しずかです。","underline":null,"options":["きょうしつは うるさいです。","きょうしつには だれも いません。","きょうしつでは 学生が ねて います。","きょうしつには おとが ありません。"],"answer":"きょうしつには おとが ありません。","note":"「しずか」（安靜）就是「おとが ない」（沒有聲音）。「だれも いません」說的是沒人，教室沒人不等於安靜，是最容易選錯的選項。"},{"id":"ja-j-0172","level":1,"section":"goi","mondai":4,"stem":"あした しけんが あります。","underline":null,"options":["あした テストが あります。","あした やすみです。","あした パーティーが あります。","あした しごとが ありません。"],"answer":"あした テストが あります。","note":"「しけん」（考試）和「テスト」意思相同。「やすみです」「パーティーが あります」「しごとが ありません」說的都是別的事。"},{"id":"ja-j-0173","level":1,"section":"goi","mondai":4,"stem":"友だちに 本を かしました。","underline":null,"options":["友だちは 私に 本を かしました。","友だちは 私から 本を かりました。","友だちが 私に 本を あげました。","私は 友だちから 本を もらいました。"],"answer":"友だちは 私から 本を かりました。","note":"「友だちに かす」（借給朋友）換成朋友的立場，就是「友だちは 私から かりる」（朋友向我借），「かす ⇄ かりる」換立場時助詞「に」也要換成「から」。「友だちは 私に 本を かしました」方向相反。"},{"id":"ja-j-0174","level":1,"section":"goi","mondai":4,"stem":"わたしは バスに のって 学校へ いきます。","underline":null,"options":["わたしは あるいて 学校へ いきます。","わたしは でんしゃで 学校へ いきます。","わたしは バスで 学校へ いきます。","わたしは じてんしゃで 学校へ いきます。"],"answer":"わたしは バスで 学校へ いきます。","note":"「バスに のって いく」（搭公車去）就是「バスで いく」，「で」表示交通方式。其他三個選項是走路、電車、腳踏車，交通工具不同。"},{"id":"ja-j-0175","level":1,"section":"goi","mondai":4,"stem":"ことしの 一月に 日本へ きました。","underline":null,"options":["らいねん 日本へ いきます。","ことしの はじめに 日本へ きました。","一年 まえに 日本へ きました。","きょねんの 一月に 日本へ きました。"],"answer":"ことしの はじめに 日本へ きました。","note":"「ことしの 一月」（今年一月）就是「ことしの はじめ」（今年年初）。「きょねんの 一月」年份不對，「一年 まえ」是從現在往回算一年，不等於今年一月。"},{"id":"ja-j-0176","level":1,"section":"goi","mondai":4,"stem":"わたしは おちゃより コーヒーの ほうが すきで、 まいにち 飲みます。","underline":null,"options":["わたしは コーヒーより おちゃの ほうが すきです。","わたしは おちゃと コーヒーが すきです。","わたしは コーヒーを あまり のみません。","わたしは コーヒーを よく のみます。"],"answer":"わたしは コーヒーを よく のみます。","note":"題面說比起茶更喜歡咖啡、每天都喝，所以是「コーヒーを よく のみます」（常喝咖啡）。「コーヒーより おちゃの ほうが すき」喜好相反；「おちゃと コーヒーが すき」沒有比較，題面也沒說喜歡茶。"},{"id":"ja-j-0177","level":1,"section":"goi","mondai":4,"stem":"しゅくだいは むずかしくないです。","underline":null,"options":["しゅくだいは やさしいです。","しゅくだいは むずかしいです。","しゅくだいは おもしろいです。","しゅくだいは ながいです。"],"answer":"しゅくだいは やさしいです。","note":"「むずかしくない」（不難）就是「やさしい」（簡單），這裡的「やさしい」是「容易」的意思。「むずかしいです」意思相反，「おもしろい」「ながい」說的是別的性質。"},{"id":"ja-j-0178","level":1,"section":"goi","mondai":4,"stem":"あの レストランは いつも おきゃくさんが おおいです。","underline":null,"options":["あの レストランは おきゃくさんが すくないです。","あの レストランは いつも すいて います。","あの レストランは いつも こんで います。","あの レストランは とおいです。"],"answer":"あの レストランは いつも こんで います。","note":"客人總是很多，就是「いつも こんで います」（總是很擠）。「すいて います」（很空）和「すくない」（少）意思相反，「とおい」說的是距離。"},{"id":"ja-j-0179","level":1,"section":"goi","mondai":4,"stem":"たなかさんの いえは 大きくないです。","underline":null,"options":["たなかさんの いえは ちいさいです。","たなかさんの いえは 大きいです。","たなかさんの いえは あたらしいです。","たなかさんの いえは ふるいです。"],"answer":"たなかさんの いえは ちいさいです。","note":"「大きくない」（不大）在四個選項裡最接近「ちいさい」（小）。「大きいです」意思相反，「あたらしい」「ふるい」說的是新舊，不是大小。"},{"id":"ja-j-0180","level":1,"section":"goi","mondai":4,"stem":"きょうは あつくないです。","underline":null,"options":["きょうは すずしいです。","きょうは あついです。","きょうは あめです。","きょうは ねむいです。"],"answer":"きょうは すずしいです。","note":"「あつくない」（不熱）在選項裡最接近「すずしい」（涼爽）。「あついです」意思相反，「あめです」「ねむいです」說的是下雨和想睡，不是溫度。"},{"id":"ja-j-0181","level":1,"section":"goi","mondai":4,"stem":"その しごとを する 人は いません。","underline":null,"options":["みんなが その しごとを します。","その しごとは おもしろいです。","その しごとは おわりました。","だれも その しごとを しません。"],"answer":"だれも その しごとを しません。","note":"「その しごとを する 人は いない」（沒有人做那份工作）就是「だれも その しごとを しない」（誰都不做）。「みんなが します」意思相反，另外兩個說的是工作有趣或已經結束。"},{"id":"ja-j-0182","level":1,"section":"goi","mondai":4,"stem":"きょうは あめが ふって います。","underline":null,"options":["きょうは てんきが いいです。","きょうは そらが くもって います。","きょうは てんきが よくないです。","きょうは ゆきが ふって います。"],"answer":"きょうは てんきが よくないです。","note":"下雨就是「てんきが よくない」（天氣不好）。「そらが くもって います」是陰天，日文裡陰天和下雨是不同的天氣；「ゆきが ふって」是下雪。"},{"id":"ja-j-0183","level":1,"section":"goi","mondai":4,"stem":"友だちから 本を かりました。","underline":null,"options":["友だちが 私に 本を かしました。","友だちが 私から 本を かりました。","私が 友だちに 本を あげました。","友だちは 本を かいました。"],"answer":"友だちが 私に 本を かしました。","note":"「友だちから かりる」（向朋友借）換成朋友的立場，就是「友だちが 私に かす」（朋友借給我）。「友だちが 私から かりました」方向相反，「あげました」是送，不是借。"},{"id":"ja-j-0184","level":1,"section":"goi","mondai":4,"stem":"きょうは 時間が ありません。","underline":null,"options":["きょうは ひまです。","きょうは げんきです。","きょうは つかれて います。","きょうは いそがしいです。"],"answer":"きょうは いそがしいです。","note":"「時間が ない」（沒時間）就是「いそがしい」（忙）。「ひまです」意思相反，「げんき」「つかれて いる」說的是身體狀況。"},{"id":"ja-j-0185","level":1,"section":"goi","mondai":4,"stem":"こうえんで さんぽしました。","underline":null,"options":["こうえんで あそびました。","こうえんを あるきました。","こうえんで すわりました。","こうえんに いきました。"],"answer":"こうえんを あるきました。","note":"「さんぽする」（散步）就是在公園裡「あるく」（走），經過的場所用「こうえんを」。「こうえんに いきました」只說去了公園，沒說做什麼，不算同義。"},{"id":"ja-j-0186","level":1,"section":"goi","mondai":4,"stem":"友だちに でんわを かけて、 一時間 話しました。","underline":null,"options":["友だちが でんわを くれました。","友だちと でんわで 話しました。","でんわを 買いました。","友だちに 手紙を 書きました。"],"answer":"友だちと でんわで 話しました。","note":"打電話給朋友、聊了一小時，就是「友だちと でんわで 話しました」（和朋友講電話）。「友だちが でんわを くれました」變成朋友打來，方向相反。"},{"id":"ja-j-0187","level":1,"section":"goi","mondai":4,"stem":"わたしは 二十さいです。","underline":null,"options":["わたしは ことし 二十さいに なります。","わたしの たんじょうびは あした です。","わたしは いま 二十さいです。","わたしは らいねん 二十さいに なります。"],"answer":"わたしは いま 二十さいです。","note":"「二十さいです」說的是現在的年齡，加上「いま」意思不變；「二十さい」念「はたち」。「ことし 二十さいに なります」是今年才滿二十，現在可能還是十九歲。"},{"id":"ja-j-0188","level":1,"section":"goi","mondai":4,"stem":"きょうしつには つくえが いっぱい あります。","underline":null,"options":["きょうしつには つくえが すこし あります。","きょうしつには つくえが たくさん あります。","きょうしつには つくえが ありません。","きょうしつには つくえが ひとつ あります。"],"answer":"きょうしつには つくえが たくさん あります。","note":"「いっぱい」和「たくさん」都是「很多」。「すこし」「ありません」「ひとつ」都跟很多相反。"},{"id":"ja-j-0189","level":1,"section":"goi","mondai":4,"stem":"その くつは 高かったです。","underline":null,"options":["その くつは とても やすいです。","その くつに とても たくさん お金を はらいました。","その くつは ながかったです。","その くつは よかったです。"],"answer":"その くつに とても たくさん お金を はらいました。","note":"鞋子「高かった」（很貴），就是買的時候付了很多錢。「やすい」意思相反，「ながかった」「よかった」說的是長度和好壞，不是價錢。"},{"id":"ja-j-0190","level":1,"section":"goi","mondai":4,"stem":"たろうさんは げんきです。","underline":null,"options":["たろうさんは びょうきです。","たろうさんは つかれて います。","たろうさんは びょうきでは ありません。","たろうさんは いそがしいです。"],"answer":"たろうさんは びょうきでは ありません。","note":"「げんき」（健康、有精神）在選項裡最接近「びょうきでは ありません」（沒有生病）。「びょうきです」意思相反，「つかれて いる」「いそがしい」跟有沒有生病無關。"},{"id":"ja-j-0191","level":1,"section":"goi","mondai":4,"stem":"わたしは 日本に きて 一年に なります。","underline":null,"options":["わたしは 来年 日本へ きます。","わたしは 一年 まえに 日本を 出ました。","わたしは 一年 まえから 日本に います。","わたしは 一年 だけ 日本に いました。"],"answer":"わたしは 一年 まえから 日本に います。","note":"「来て 一年に なる」（來了一年）就是從一年前開始一直在日本。「一年 だけ 日本に いました」是過去待過一年、現在已經不在，最容易選錯。"},{"id":"ja-j-0192","level":1,"section":"goi","mondai":4,"stem":"友だちに たんじょうびの プレゼントを あげました。","underline":null,"options":["友だちが 私に プレゼントを あげました。","友だちは 私から プレゼントを もらいました。","私が 友だちから プレゼントを もらいました。","友だちは プレゼントを 買いませんでした。"],"answer":"友だちは 私から プレゼントを もらいました。","note":"「友だちに あげる」（送給朋友）換成朋友的立場，就是「友だちは 私から もらう」（朋友從我這裡收到）。「私が 友だちから もらいました」方向相反；別人送我東西要說「くれる」，「友だちが 私に あげました」這個說法本身就不成立。"},{"id":"ja-j-0193","level":1,"section":"goi","mondai":4,"stem":"あした しごとが ありません。","underline":null,"options":["あした やすみです。","あした しごとが おそく おわります。","あした しごとに いきます。","あした しごとが はじまります。"],"answer":"あした やすみです。","note":"明天沒有工作，就是「あした やすみです」（明天休假）。其他三個選項都表示明天要工作。"},{"id":"ja-j-0194","level":1,"section":"goi","mondai":4,"stem":"この みせの ケーキは あまくないです。","underline":null,"options":["この みせの ケーキは あまいです。","この みせの ケーキは からい です。","この みせの ケーキは あまく ありません。","この みせの ケーキは おいしくないです。"],"answer":"この みせの ケーキは あまく ありません。","note":"「あまくないです」和「あまく ありません」都是「あまい」的否定，只是說法不同。「おいしくないです」說的是好不好吃，不是甜不甜，最容易選錯。"},{"id":"ja-j-0195","level":1,"section":"goi","mondai":4,"stem":"たなかさんは いつも しずかです。","underline":null,"options":["たなかさんは いつも あまり 話しません。","たなかさんは いつも たくさん 話します。","たなかさんは いつも うるさいです。","たなかさんは いつも おこって います。"],"answer":"たなかさんは いつも あまり 話しません。","note":"「しずか」用在人身上，是指話不多、很安靜，所以等於「あまり 話しません」。「たくさん 話します」「うるさい」意思相反，「おこって いる」是在生氣。"},{"id":"ja-j-0196","level":1,"section":"goi","mondai":4,"stem":"たろうさんは 日本ごを 話すのが じょうずです。","underline":null,"options":["たろうさんは 日本ごを 上手に 話します。","たろうさんは 日本ごが ぜんぜん わかりません。","たろうさんは 日本ごが すきじゃ ありません。","たろうさんは 日本ごを ならって います。"],"answer":"たろうさんは 日本ごを 上手に 話します。","note":"「話すのが じょうず」（擅長說）可以換成「上手に 話します」（說得很好），只是句型不同。「ならって います」是正在學，不代表已經說得好。"},{"id":"ja-j-0197","level":1,"section":"goi","mondai":4,"stem":"わたしは あした しゅくだいを 出します。","underline":null,"options":["あした しゅくだいを はじめます。","あした、 わたしは しゅくだいを 先生に もって いきます。","あした しゅくだいを かいます。","あした しゅくだいを かえします。"],"answer":"あした、 わたしは しゅくだいを 先生に もって いきます。","note":"「しゅくだいを 出す」是「交作業」，也就是把作業拿去給老師。「かえします」是歸還，交作業不是還東西；「はじめます」「かいます」意思完全不同。"},{"id":"ja-j-0198","level":1,"section":"goi","mondai":4,"stem":"わたしは スペインから きました。","underline":null,"options":["わたしは スペインへ いきます。","わたしは スペイン人です。","わたしは スペインの 人と ともだちです。","わたしは スペインごを 話します。"],"answer":"わたしは スペイン人です。","note":"自我介紹時說「〜から きました」（從〜來），就是在說自己的國籍，所以等於「スペイン人です」。「スペインへ いきます」方向相反，「スペインごを 話します」說的是會的語言，不是來自哪裡。"},{"id":"ja-j-0199","level":1,"section":"goi","mondai":4,"stem":"わたしは ピアノを ならって、 まいにち れんしゅうします。","underline":null,"options":["わたしは ピアノが よく わかります。","わたしは ピアノを 売って います。","わたしは ピアノを 買いました。","わたしは ピアノの れんしゅうを して います。"],"answer":"わたしは ピアノの れんしゅうを して います。","note":"「ならって、まいにち れんしゅうする」（在學、每天練習）就是「れんしゅうを して います」（正在練習）。「よく わかります」「売って います」「買いました」都不是題面的意思。"},{"id":"ja-j-0200","level":1,"section":"bunpou","mondai":1,"stem":"わたし（　　）たなかです。","underline":null,"options":["が","は","を","に"],"answer":"は","note":"「わたしは たなかです」意思是「我是田中」，自我介紹時用「は」標出主題。「が」會變成「田中就是我」的指認語氣，要有人先問「誰是田中」才用得上。"},{"id":"ja-j-0201","level":1,"section":"bunpou","mondai":1,"stem":"きのう ともだち（　　）えいがを 見ました。","underline":null,"options":["を","と","へ","に"],"answer":"と","note":"句意是「昨天和朋友看了電影」，「と」表示一起做動作的對象。「に」用在見面、給予這類動作的對象，「見る」不這樣用；「を」已經用在「えいが」上了。"},{"id":"ja-j-0202","level":1,"section":"bunpou","mondai":1,"stem":"あさ、コーヒー（　　）のみました。","underline":null,"options":["が","に","を","と"],"answer":"を","note":"「を」標出「のむ」的受詞，「コーヒーを のみました」是「早上喝了咖啡」。「が」不能標他動詞的受詞，「と」會變成「和咖啡一起喝」，意思不通。"},{"id":"ja-j-0203","level":1,"section":"bunpou","mondai":1,"stem":"学校（　　）バスで いきます。","underline":null,"options":["を","で","へ","が"],"answer":"へ","note":"「へ」表示移動的方向，「学校へ バスで いきます」是「搭公車去學校」。「で」是手段或動作地點，這句已經用在「バス」上；「を」接「いく」表示經過的地方，不是目的地。"},{"id":"ja-j-0204","level":1,"section":"bunpou","mondai":1,"stem":"きょう（　　）何曜日 ですか。","underline":null,"options":["が","を","は","に"],"answer":"は","note":"「きょうは 何曜日ですか」是「今天星期幾」，用「は」把「きょう」提出來當主題。疑問詞放在後面當述語時，前面用「は」，用「が」會很不自然。"},{"id":"ja-j-0205","level":1,"section":"bunpou","mondai":1,"stem":"ぎんこうは 駅（　　）まえに あります。","underline":null,"options":["を","の","が","は"],"answer":"の","note":"「駅の まえ」是「車站前面」，名詞接方位詞「まえ」要用「の」連起來。「が」「は」都不能把兩個名詞接成一個詞組。"},{"id":"ja-j-0206","level":1,"section":"bunpou","mondai":1,"stem":"七時（　　）おきます。","underline":null,"options":["と","に","を","で"],"answer":"に","note":"具體時間點後面加「に」，「七時に おきます」是「七點起床」。「で」不能表示時間點，「と」「を」也不接時間。"},{"id":"ja-j-0207","level":1,"section":"bunpou","mondai":1,"stem":"きょうしつ（　　）日本語を べんきょうします。","underline":null,"options":["に","へ","を","で"],"answer":"で","note":"「で」表示動作發生的地點，「きょうしつで べんきょうします」是「在教室讀書」。「に」是存在或到達的位置，用在「あります」「いきます」這類動詞，不用在讀書這種動作上。"},{"id":"ja-j-0208","level":1,"section":"bunpou","mondai":1,"stem":"としょかん（　　）本を よみます。","underline":null,"options":["に","へ","を","で"],"answer":"で","note":"「としょかんで 本を よみます」是「在圖書館看書」，看書是動作，地點用「で」。「に」最容易混淆，它表示存在或到達的地點，例如「としょかんに 行きます」。"},{"id":"ja-j-0209","level":1,"section":"bunpou","mondai":1,"stem":"たなかさん（　　）アメリカへ いきました。","underline":null,"options":["を","に","で","は"],"answer":"は","note":"句意是「田中先生去了美國」，用「は」把「たなかさん」當成主題。「で」是地點或手段，不能接在人後面表示做動作的人；「を」「に」也不行。"},{"id":"ja-j-0210","level":1,"section":"bunpou","mondai":1,"stem":"つくえの 上に 本（　　）あります。","underline":null,"options":["に","を","が","は"],"answer":"が","note":"「〜に 〜が あります」是描述某處有某物的基本句型，「つくえの 上に 本が あります」是「桌上有書」，存在的東西用「が」。「は」會帶出「書的話倒是有」的對比語氣，單純描述時不用。"},{"id":"ja-j-0211","level":1,"section":"bunpou","mondai":1,"stem":"きょうしつに 学生（　　）三人 います。","underline":null,"options":["を","は","に","が"],"answer":"が","note":"「きょうしつに 学生が 三人 います」是「教室裡有三個學生」，人或動物用「います」，存在的主體用「が」。數量「三人」直接放在動詞前；「は」帶對比語氣，這裡不自然。"},{"id":"ja-j-0212","level":1,"section":"bunpou","mondai":1,"stem":"おかね（　　）ぜんぜん ありませんから、何も 買いません。","underline":null,"options":["を","に","へ","が"],"answer":"が","note":"「おかねが ありません」是「沒有錢」，「ある」的主體用「が」；整句是「完全沒錢，所以什麼都不買」。「を」最容易誤選，但「ある」不是他動詞，不接受詞。"},{"id":"ja-j-0213","level":1,"section":"bunpou","mondai":1,"stem":"わたしは ねこ（　　）すきです。","underline":null,"options":["を","に","が","へ"],"answer":"が","note":"「すき」是な形容詞，喜歡的對象用「が」：「わたしは ねこが すきです」是「我喜歡貓」。中文的「貓」像受詞，容易誤選「を」，但標準日文用「が」。"},{"id":"ja-j-0214","level":1,"section":"bunpou","mondai":1,"stem":"日本語（　　）すこし わかります。","underline":null,"options":["を","へ","に","が"],"answer":"が","note":"「わかる」的對象用「が」，「日本語が すこし わかります」是「懂一點日文」。「を」是常見錯誤，「わかる」不是他動詞，不用「を」。"},{"id":"ja-j-0215","level":1,"section":"bunpou","mondai":1,"stem":"ピアノ（　　）できます。","underline":null,"options":["を","が","に","へ"],"answer":"が","note":"「できる」表示能力，會的東西用「が」：「ピアノが できます」是「會彈鋼琴」。「を」是常見誤選，要換成「ピアノを ひきます」才用「を」。"},{"id":"ja-j-0216","level":1,"section":"bunpou","mondai":1,"stem":"新しい かばん（　　）ほしいです。","underline":null,"options":["を","と","に","が"],"answer":"が","note":"「ほしい」是い形容詞，想要的東西用「が」：「新しい かばんが ほしいです」是「想要新包包」。「を」容易誤選，但「ほしい」不是動詞，前面用「が」。"},{"id":"ja-j-0217","level":1,"section":"bunpou","mondai":1,"stem":"毎日 一時間 ピアノ（　　）れんしゅうします。","underline":null,"options":["に","が","を","へ"],"answer":"を","note":"「れんしゅうする」是他動詞，練習的東西用「を」：「每天練一小時鋼琴」。「が」容易跟「ピアノが できます」搞混，那是能力的說法，練習要用「を」。"},{"id":"ja-j-0218","level":1,"section":"bunpou","mondai":1,"stem":"ねつ（　　）あります。","underline":null,"options":["を","と","に","が"],"answer":"が","note":"「ねつが あります」是「發燒」，日文說成「有熱度」，主體用「が」。「を」不能接「ある」，「に」「と」也不成立。"},{"id":"ja-j-0219","level":1,"section":"bunpou","mondai":1,"stem":"きょう（　　）あした、しけんが あります。","underline":null,"options":["か","が","に","を"],"answer":"か","note":"「Aか B」表示二選一，「きょうか あした、しけんが あります」是「今天或明天有考試」。「が」「に」「を」都不能把兩個名詞並列起來。"},{"id":"ja-j-0220","level":1,"section":"bunpou","mondai":1,"stem":"その 本は たなかさん（　　）もらいました。","underline":null,"options":["に","へ","を","と"],"answer":"に","note":"「人に もらう」表示從某人那裡得到，「その 本は たなかさんに もらいました」是「那本書是從田中先生那裡拿到的」，也可以說「から」。「へ」只表示方向，不能表示東西從誰那裡來；「と」是「和田中先生一起」，不是這句的意思。"},{"id":"ja-j-0221","level":1,"section":"bunpou","mondai":1,"stem":"子どもに 本（　　）あげます。","underline":null,"options":["が","に","を","と"],"answer":"を","note":"「子どもに 本を あげます」是「把書給小孩」：給的對象用「に」，給的東西用「を」。「に」已經用在「子ども」上，「が」也不能標「あげる」的受詞。"},{"id":"ja-j-0222","level":1,"section":"bunpou","mondai":1,"stem":"学校は 八時（　　）三時までです。","underline":null,"options":["と","へ","に","から"],"answer":"から","note":"「AからBまで」表示範圍的起點和終點，「学校は 八時から 三時までです」是「學校從八點到三點」。「に」只表示時間點，不能和「まで」配成一組。"},{"id":"ja-j-0223","level":1,"section":"bunpou","mondai":1,"stem":"とうきょう（　　）おおさかまで しんかんせんで いきます。","underline":null,"options":["に","を","から","と"],"answer":"から","note":"「とうきょうから おおさかまで」是「從東京到大阪」，「から」是起點、「まで」是終點。「に」是到達點，放在起點的位置不對。"},{"id":"ja-j-0224","level":1,"section":"bunpou","mondai":1,"stem":"ペン（　　）三本 あります。","underline":null,"options":["を","が","に","へ"],"answer":"が","note":"「ペンが 三本 あります」是「有三枝筆」，存在的東西用「が」，數量「三本」放在動詞前面。「を」不能接「ある」。"},{"id":"ja-j-0225","level":1,"section":"bunpou","mondai":1,"stem":"毎日 日本語（　　）べんきょうします。","underline":null,"options":["が","に","を","と"],"answer":"を","note":"「べんきょうする」的內容用「を」：「毎日 日本語を べんきょうします」是「每天學日文」。「が」會被誤選，但「べんきょうする」是他動詞，要用「を」。"},{"id":"ja-j-0226","level":1,"section":"bunpou","mondai":1,"stem":"毎日 学校で ともだちに あい（　　）。とても たのしいです。","underline":null,"options":["ます","ません","ました","ませんでした"],"answer":"ます","note":"「毎日」表示習慣，用現在式「ます」；後句「とても たのしいです」也說明是開心的事。「ました」「ませんでした」是過去式，跟「毎日」和後句的現在式不合；「ません」變成「每天都見不到」，和「很開心」矛盾。"},{"id":"ja-j-0227","level":1,"section":"bunpou","mondai":1,"stem":"きのう、おさけを のみ（　　）。","underline":null,"options":["ます","ません","ました","ましょう"],"answer":"ました","note":"「きのう」是過去，要用「ました」：「昨天喝了酒」。「ます」「ません」是現在或未來，「ましょう」是邀約，都和「きのう」不合。"},{"id":"ja-j-0228","level":1,"section":"bunpou","mondai":1,"stem":"きのうは あめ（　　）。","underline":null,"options":["です","でした","じゃありません","ありません"],"answer":"でした","note":"名詞句的過去式用「でした」，「きのうは あめでした」是「昨天下雨」。「です」是現在式；「じゃありません」是否定，而且也是現在式，不能用在「きのう」。"},{"id":"ja-j-0229","level":1,"section":"bunpou","mondai":1,"stem":"私は 学生 では （　　）。","underline":null,"options":["あります","ありません","ありました","です"],"answer":"ありません","note":"「〜では ありません」是名詞句的否定，「私は 学生では ありません」是「我不是學生」。「あります」「ありました」是肯定，「では です」不是日文的說法。"},{"id":"ja-j-0230","level":1,"section":"bunpou","mondai":1,"stem":"その カメラは とても （　　）です。","underline":null,"options":["たかい","たかいな","たかく","たかくて"],"answer":"たかい","note":"い形容詞直接加「です」：「その カメラは とても たかいです」是「那台相機很貴」。「たかいな」是把な形容詞的規則套到い形容詞上的錯誤；「たかく」「たかくて」後面不能直接接「です」。"},{"id":"ja-j-0231","level":1,"section":"bunpou","mondai":1,"stem":"この りんごは あまり （　　）。","underline":null,"options":["おいしいです","おいしくです","おいしかったです","おいしくないです"],"answer":"おいしくないです","note":"「あまり」後面要接否定，「あまり おいしくないです」是「不太好吃」。「おいしいです」「おいしかったです」是肯定，和「あまり」不合；「おいしくです」不是正確的變化。"},{"id":"ja-j-0232","level":1,"section":"bunpou","mondai":1,"stem":"きのう 食べた りょうりは とても （　　）です。","underline":null,"options":["おいしかった","おいしく","おいしい","おいしくない"],"answer":"おいしかった","note":"說的是「昨天吃的菜」，評價用過去式：い形容詞的過去式是「おいしかった」，再加「です」。「おいしく」後面不能直接接「です」；「おいしい」是現在式，和昨天的事不搭。"},{"id":"ja-j-0233","level":1,"section":"bunpou","mondai":1,"stem":"きょうしつは あまり （　　）です。","underline":null,"options":["しずかじゃ ない","しずかで","しずかな","しずかでした"],"answer":"しずかじゃ ない","note":"「あまり」要接否定，題目最後已經有「です」，所以填「しずかじゃ ない」，合起來是「しずかじゃ ないです」（不太安靜）。「しずかでした」是肯定；「しずかな」「しずかで」後面不能直接接「です」。"},{"id":"ja-j-0234","level":1,"section":"bunpou","mondai":1,"stem":"たなかさんは とても しんせつ （　　） 人です。","underline":null,"options":["の","に","で","な"],"answer":"な","note":"な形容詞修飾名詞要加「な」：「しんせつな 人」是「親切的人」。「の」是名詞修飾名詞時用的，容易混淆，な形容詞不用「の」。"},{"id":"ja-j-0235","level":1,"section":"bunpou","mondai":1,"stem":"きょうは 雨ですから、外へ いき （　　）。","underline":null,"options":["ます","ましょう","たいです","ません"],"answer":"ません","note":"前半句「今天下雨」是理由，所以後面說「不出去」，用「ません」。「ましょう」是邀約，「たいです」是想要，都和下雨這個理由接不起來。"},{"id":"ja-j-0236","level":1,"section":"bunpou","mondai":1,"stem":"つかれましたから、すこし やすみ（　　）です。","underline":null,"options":["ます","たい","ました","ません"],"answer":"たい","note":"動詞ます形去掉「ます」加「たい」表示想做：「つかれましたから、すこし やすみたいです」是「累了，想休息一下」。題目後面已經有「です」，「ます」「ました」「ません」後面都不能再接「です」。"},{"id":"ja-j-0237","level":1,"section":"bunpou","mondai":1,"stem":"しごとが おわってから 何（　　）食べに 行きませんか。","underline":null,"options":["に","を","か","が"],"answer":"か","note":"「何か」是「某個東西」，「何か 食べに 行きませんか」是「要不要去吃點什麼」。「何を」是在問「吃什麼」，和邀約的「行きませんか」接不起來。"},{"id":"ja-j-0238","level":1,"section":"bunpou","mondai":1,"stem":"つくえの 上に 本が 三（　　）あります。","underline":null,"options":["つ","ほん","さつ","にん"],"answer":"さつ","note":"書本這類成冊的東西用量詞「さつ」：「本が 三さつ あります」是「有三本書」。「ほん（本）」是筆、瓶子這類細長物品的量詞，容易和漢字「本」搞混；「にん」用在人。"},{"id":"ja-j-0239","level":1,"section":"bunpou","mondai":1,"stem":"その こうえんで 子どもが あそんで （　　）。","underline":null,"options":["です","います","あります","なります"],"answer":"います","note":"「て形＋います」表示動作正在進行，「子どもが あそんで います」是「小孩正在玩」。「あります」用在物品，「あそんで あります」不成立；「なります」「です」也不能接在て形後面。"},{"id":"ja-j-0240","level":1,"section":"bunpou","mondai":1,"stem":"あさごはんを （　　） から、学校へ いきます。","underline":null,"options":["たべる","たべて","たべた","たべます"],"answer":"たべて","note":"「て形＋から」表示做完前一件事再做下一件：「吃完早餐再去學校」。「たべたから」「たべるから」的「から」變成表示原因的「因為」，不是先後順序。"},{"id":"ja-j-0241","level":1,"section":"bunpou","mondai":1,"stem":"その 本を かして （　　）。","underline":null,"options":["です","ください","たいです","なります"],"answer":"ください","note":"「て形＋ください」是請求：「その 本を かして ください」是「請借我那本書」。「たいです」接在ます形去掉「ます」的地方，不接て形；「です」「なります」也不能接在て形後面。"},{"id":"ja-j-0242","level":1,"section":"bunpou","mondai":1,"stem":"ここで しゃしんを とって （　　）か。","underline":null,"options":["なります","たいです","もいいです","ください"],"answer":"もいいです","note":"「て形＋も いいですか」是請求許可：「ここで しゃしんを とっても いいですか」是「可以在這裡拍照嗎」。「ください」後面不能接「か」；「たいです」接在ます形去掉「ます」的地方，不接て形。"},{"id":"ja-j-0243","level":1,"section":"bunpou","mondai":1,"stem":"きょうしつでは たばこを すっては （　　）。","underline":null,"options":["いいです","ください","いけません","たいです"],"answer":"いけません","note":"「〜ては いけません」表示禁止：「教室裡不可以抽菸」。「いいです」容易誤選，但表示允許要說「すっても いいです」，前面是「ても」不是「ては」。"},{"id":"ja-j-0244","level":1,"section":"bunpou","mondai":1,"stem":"あさ おきて、コーヒーを （　　）、ニュースを 見ます。","underline":null,"options":["のんだ","のみます","のんで","のむ"],"answer":"のんで","note":"動詞て形可以把動作依序串起來：「早上起床，喝了咖啡，再看新聞」。「のんだ」「のむ」「のみます」都不能放在逗號前接下一個動作。"},{"id":"ja-j-0245","level":1,"section":"bunpou","mondai":1,"stem":"その みせの ケーキは おいしくて、（　　）です。","underline":null,"options":["やすくて","やすく","やすい","やすくない"],"answer":"やすい","note":"い形容詞用「くて」串起兩個評價：「その みせの ケーキは おいしくて、やすいです」是「那家店的蛋糕又好吃又便宜」。「て」只連接同方向的評價，「やすくない」方向相反要改用「が」或「けど」；「やすく」「やすくて」後面不能直接接「です」。"},{"id":"ja-j-0246","level":1,"section":"bunpou","mondai":1,"stem":"きょうは あつい（　　）、まどを あけました。","underline":null,"options":["と","から","けど","が"],"answer":"から","note":"前半句「今天很熱」是開窗的理由，用「から」。「けど」「が」是「雖然…但是」，會變成「雖然熱還是開了窗」，邏輯相反。"},{"id":"ja-j-0247","level":1,"section":"bunpou","mondai":1,"stem":"きのうは いそがしかった（　　）、しゅくだいを しませんでした。","underline":null,"options":["と","けど","が","から"],"answer":"から","note":"「いそがしかったから」是「因為很忙」，說明沒寫作業的原因。「けど」「が」表示轉折，會變成「雖然很忙卻沒寫作業」，不合邏輯。"},{"id":"ja-j-0248","level":1,"section":"bunpou","mondai":1,"stem":"うちに 来る （　　）に 電話して ください。","underline":null,"options":["まえ","あと","うしろ","うえ"],"answer":"まえ","note":"「辭書形＋まえに」表示「在做某事之前」：「來我家之前請打電話」。「あと」要接た形，說成「来た あとで」，不能接「来る」。"},{"id":"ja-j-0249","level":1,"section":"bunpou","mondai":1,"stem":"しゅくだいを した （　　）で、テレビを 見ます。","underline":null,"options":["あと","まえ","なか","とき"],"answer":"あと","note":"「た形＋あとで」表示「做完之後」：「寫完作業後看電視」。「まえ」要接辭書形，「した まえ」不成立；「とき」後面不接「で」。"},{"id":"ja-j-0250","level":1,"section":"bunpou","mondai":1,"stem":"私は 中国へ 行った こと（　　）あります。","underline":null,"options":["を","が","に","へ"],"answer":"が","note":"「た形＋ことが あります」表示有過某種經驗：「私は 中国へ 行った ことが あります」是「我去過中國」。「ある」的主體用「が」，「を」不能接「ある」。"},{"id":"ja-j-0251","level":1,"section":"bunpou","mondai":1,"stem":"スーパーで パンや ぎゅうにゅう（　　）を 買いました。","underline":null,"options":["を","へ","に","など"],"answer":"など","note":"「AやBなど」表示只列出一部分：「在超市買了麵包、牛奶等等」。空格後面已經有「を」，再填「を」就重複了；「へ」「に」也不能接在這裡。"},{"id":"ja-j-0252","level":1,"section":"bunpou","mondai":1,"stem":"きょうは てんき（　　）いいですから、こうえんへ 行きましょう。","underline":null,"options":["が","を","の","に"],"answer":"が","note":"「てんきが いい」是「天氣好」，い形容詞「いい」的主體用「が」。「の」只在修飾名詞時可以代替「が」，例如「てんきの いい 日」，這裡後面接的是「ですから」。"},{"id":"ja-j-0253","level":1,"section":"bunpou","mondai":1,"stem":"きのう、ともだち（　　）うちへ 来ました。","underline":null,"options":["を","に","が","で"],"answer":"が","note":"「ともだちが うちへ 来ました」是「朋友來我家了」，來的人是主詞，用「が」。「に」「を」都不能標出做動作的人，「で」是地點或手段。"},{"id":"ja-j-0254","level":1,"section":"bunpou","mondai":1,"stem":"中国語 と えいご（　　）、どちらが むずかしいですか。","underline":null,"options":["に","と","の","が"],"answer":"と","note":"比較兩樣東西時說「AとBと、どちらが〜ですか」：「中文和英文，哪個比較難」。「に」「の」「が」都不能把兩個比較的對象並列。"},{"id":"ja-j-0255","level":1,"section":"bunpou","mondai":1,"stem":"とうきょうは おおさか（　　）大きいです。","underline":null,"options":["の","が","と","より"],"answer":"より","note":"「AはBより〜」表示A比B更〜：「とうきょうは おおさかより 大きいです」是「東京比大阪大」。「と」「が」「の」都不能表示比較的基準。"}];
